import { useMemo, useCallback, useState } from "react";
import { Button } from "@ui/components/Button";
import { useGrowl } from "@ui/components/Growl";
import { useDeckStore } from "./useDeckStore";
import { useTranslation } from "../i18n/I18nProvider";
import { ReviewMode } from "../review/types";
import { DownloadIcon, EditIcon, FlashcardsIcon, LearnIcon, MatchIcon, RefreshIcon, SpellIcon, TrashIcon, TypeIcon } from "../components/icons";
import { StreakHistoryModal } from "./StreakHistoryModal";

type DeckManagerProps = {
  isAuthenticated: boolean;
  syncStatus: "idle" | "syncing" | "error" | "success";
  syncError?: string;
  lastSyncedLabel?: string;
  lockStatus?: "idle" | "acquiring" | "acquired" | "blocked" | "error";
  onEditDeck: (deckId: string) => void;
  onReviewDeck: (deckId: string, mode: ReviewMode) => void;
  onNewDeck?: () => void;
};

const formatDateTime = (date: Date | undefined) =>
  date
    ? new Intl.DateTimeFormat(undefined, {
        dateStyle: "medium",
        timeStyle: "short"
      }).format(date)
    : "—";

export const DeckManager = ({
  isAuthenticated,
  syncStatus,
  syncError,
  lockStatus = "idle",
  onEditDeck,
  onReviewDeck,
  onNewDeck
}: DeckManagerProps) => {
  const { t } = useTranslation();
  const { showGrowl } = useGrowl();
  const decks = useDeckStore((state) => state.decks);
  const deleteDeck = useDeckStore((state) => state.deleteDeck);
  const streakCount = useDeckStore((state) => state.streakCount);
  const xp = useDeckStore((state) => state.xp);
  const level = useDeckStore((state) => state.level);
  const reviewActivity = useDeckStore((state) => state.reviewActivity);
  const xpProgress = xp % 100;
  const cardStats = useDeckStore((state) => state.cardStats);
  const resetDeckStats = useDeckStore((state) => state.resetDeckStats);
  const [isStreakHistoryOpen, setIsStreakHistoryOpen] = useState(false);

  const exportDeckToCsv = useCallback(async (deck: typeof decks[number]) => {
    const escapeValue = (value: string) => `"${value.replace(/"/g, '""')}"`;
    const rows = deck.cards.map((card) => `${escapeValue(card.front)},${escapeValue(card.back)}`);
    const csvContent = ["front,back", ...rows].join("\n");
    const safeTitle = deck.title.trim().replace(/[^a-z0-9-_]+/gi, "_") || deck.id;
    const filename = `${safeTitle}.csv`;
    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });

    // Prefer Web Share on mobile/webviews where downloads are blocked.
    const canShareFile =
      typeof navigator !== "undefined" &&
      typeof navigator.canShare === "function" &&
      navigator.canShare({ files: [new File([blob], filename, { type: blob.type })] });
    if (canShareFile && navigator.share) {
      try {
        await navigator.share({
          title: filename,
          files: [new File([blob], filename, { type: blob.type })]
        });
        return;
      } catch (error) {
        // fall through to other fallbacks
        console.warn("Share failed, falling back to download", error);
      }
    }

    if (navigator.share) {
      try {
        await navigator.share({
          title: filename,
          text: csvContent
        });
        return;
      } catch (error) {
        console.warn("Text share failed, trying download", error);
      }
    }

    try {
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = filename;
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
      return;
    } catch (error) {
      console.warn("Download fallback failed", error);
    }

    if (navigator.clipboard?.writeText) {
      try {
        await navigator.clipboard.writeText(csvContent);
        showGrowl({ tone: "success", message: "CSV copied to clipboard" });
        return;
      } catch (error) {
        console.warn("Clipboard write failed", error);
      }
    }

    showGrowl({ tone: "warning", message: "Export not supported on this device." });
  }, [showGrowl, decks]);

  const computeDeckStats = useCallback(
    (deck: typeof decks[number]) => {
      const stats = cardStats[deck.id] ?? {};
      let known = 0;
      let unknown = 0;
      let unsure = 0;
      let fresh = 0;
      deck.cards.forEach((card) => {
        const stat = stats[card.id];
        const attempts = (stat?.correct ?? 0) + (stat?.incorrect ?? 0);
        if (attempts === 0) {
          fresh += 1;
          return;
        }
        const accuracy = (stat?.correct ?? 0) / attempts;
        if (accuracy >= 0.75) {
          known += 1;
        } else if (accuracy <= 0.25) {
          unknown += 1;
        } else {
          unsure += 1;
        }
      });
      const totalCards = deck.cards.length;
      const percent = (value: number) =>
        totalCards === 0 ? 0 : Math.round((value * 100) / totalCards);
      return {
        known,
        unknown,
        unsure,
        fresh,
        knownPct: percent(known),
        unknownPct: percent(unknown),
        unsurePct: percent(unsure),
        freshPct: percent(fresh)
      };
    },
    [cardStats]
  );

  const sortedDecks = useMemo(() => {
    const getTimestamp = (deck: (typeof decks)[number]) =>
      Math.max(deck.updatedAt.getTime(), deck.createdAt.getTime());
    return [...decks].sort((a, b) => getTimestamp(b) - getTimestamp(a));
  }, [decks]);

  const lockOrErrorBanner = useMemo(() => {
    if (isAuthenticated && (lockStatus === "blocked" || lockStatus === "error")) {
      return {
        className:
          lockStatus === "blocked"
            ? "text-sm text-amber-500 dark:text-amber-400"
            : "text-sm text-red-500 dark:text-red-400",
        text:
          lockStatus === "blocked"
            ? t("drive.autoSyncBlocked")
            : t("drive.autoSyncLockError")
      };
    }
    if (syncStatus === "error" && syncError) {
      return {
        className: "text-sm text-red-500 dark:text-red-400",
        text: t("drive.autoSyncError", { message: syncError })
      };
    }
    return null;
  }, [isAuthenticated, lockStatus, syncStatus, syncError, t]);

  const handleDelete = (deckId: string) => {
    const deck = decks.find((item) => item.id === deckId);
    if (!deck) {
      return;
    }
    const confirmed = window.confirm(t("deck.confirmDelete", { title: deck.title }));
    if (confirmed) {
      deleteDeck(deckId);
    }
  };

  return (
    <>
      <div className="space-y-6">
      <header className="flex flex-wrap items-center justify-between gap-3">
        <div>
          <h2 className="text-2xl font-semibold text-slate-900 dark:text-slate-100">
            {t("deck.workspaceTitle")}
          </h2>
          <p className="text-sm text-slate-600 dark:text-slate-400">
            {isAuthenticated ? t("deck.workspaceSubtitleAuthed") : t("deck.workspaceSubtitleGuest")}
          </p>
          <div className="mt-1 flex flex-wrap items-center gap-3 text-sm">
            <button
              type="button"
              className="inline-flex items-center gap-2 rounded-full bg-emerald-100/80 px-3 py-1 text-emerald-800 transition hover:bg-emerald-100 dark:bg-emerald-500/20 dark:text-emerald-100 dark:hover:bg-emerald-500/30"
              onClick={() => setIsStreakHistoryOpen(true)}
              title={t("deck.streakHistoryCta")}
              aria-label={t("deck.streakHistoryCta")}
            >
              🔥 {streakCount > 0 ? t("deck.streakActive", { count: streakCount }) : t("deck.streakEmpty")}
            </button>
            <div className="inline-flex items-center gap-2 rounded-full bg-slate-200/80 px-3 py-1 text-slate-800 dark:bg-slate-800/60 dark:text-slate-100">
              🛡️ {t("deck.levelLabel", { level })}
              <span className="text-xs text-slate-600 dark:text-slate-300">
                {xpProgress}/100 XP
              </span>
            </div>
          </div>
        </div>
      </header>

      {lockOrErrorBanner && (
        <p className={lockOrErrorBanner.className}>{lockOrErrorBanner.text}</p>
      )}

      {sortedDecks.length === 0 ? (
        <div className="ui-empty-panel">
          {t("deck.emptyState")}
        </div>
      ) : (
        <ul className="ui-vstack-4">
          {sortedDecks.map((deck) => {
            const stats = computeDeckStats(deck);
            return (
              <li
                key={deck.id}
                className="ui-surface-panel"
              >
              <div className="flex flex-wrap items-start justify-between gap-3">
                <div className="space-y-1">
                  <h3 className="text-lg font-semibold text-slate-900 dark:text-slate-100">
                    {deck.title}
                  </h3>
                  <p className="ui-text-xs-muted">
                    {t("deck.listSubtitle", {
                      count: deck.cards.length,
                      updated: formatDateTime(deck.updatedAt)
                    })}
                  </p>
                  {deck.description && (
                    <p className="text-sm text-slate-600 dark:text-slate-400">{deck.description}</p>
                  )}
                </div>
                <div className="flex flex-wrap items-center gap-1">
                  <Button size="icon" variant="ghost" title={t("deck.editDeck")} onClick={() => onEditDeck(deck.id)}>
                    <EditIcon className="h-4 w-4" />
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    title={t("deck.exportDeck")}
                    onClick={() => exportDeckToCsv(deck)}
                  >
                    <DownloadIcon className="h-4 w-4" />
                  </Button>
                  <Button
                    size="icon"
                    variant="ghost"
                    title={t("deck.deleteDeck")}
                    className="text-red-500 hover:text-red-400 dark:text-red-400 dark:hover:text-red-300"
                    onClick={() => handleDelete(deck.id)}
                  >
                    <TrashIcon className="h-4 w-4" />
                  </Button>
                </div>
                {deck.cards.length > 0 && (
                  <div className="mt-3 w-full space-y-2">
                    <div className="ui-progress-bar">
                      <span
                        className="ui-progress-segment known"
                        style={{ flexBasis: `${stats.knownPct}%`, flexGrow: stats.knownPct, minWidth: stats.knownPct ? "4px" : "0px" }}
                      />
                      <span
                        className="ui-progress-segment unsure"
                        style={{ flexBasis: `${stats.unsurePct}%`, flexGrow: stats.unsurePct, minWidth: stats.unsurePct ? "4px" : "0px" }}
                      />
                      <span
                        className="ui-progress-segment unknown"
                        style={{ flexBasis: `${stats.unknownPct}%`, flexGrow: stats.unknownPct, minWidth: stats.unknownPct ? "4px" : "0px" }}
                      />
                      <span
                        className="ui-progress-segment fresh"
                        style={{ flexBasis: `${stats.freshPct}%`, flexGrow: stats.freshPct, minWidth: stats.freshPct ? "4px" : "0px" }}
                      />
                    </div>
                    <div className="flex flex-col gap-2 text-xs text-slate-600 dark:text-slate-300 sm:flex-row sm:flex-wrap sm:items-center sm:gap-4">
                      <span>{t("deck.stats.known", { percent: stats.knownPct })}</span>
                      <span>{t("deck.stats.unsure", { percent: stats.unsurePct })}</span>
                      <span>{t("deck.stats.unknown", { percent: stats.unknownPct })}</span>
                      <span>{t("deck.stats.fresh", { percent: stats.freshPct })}</span>
                      <Button
                        size="icon"
                        variant="ghost"
                        title={t("deck.resetStats")}
                        onClick={() => {
                          if (window.confirm(t("deck.resetStatsConfirm"))) {
                            resetDeckStats(deck.id);
                          }
                        }}
                      >
                        <RefreshIcon className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                )}
              </div>
              <div className="mt-4 space-y-2">
                <div className="flex flex-wrap items-center gap-2">
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length === 0}
                    onClick={() => onReviewDeck(deck.id, "flashcards")}
                  >
                    <span className="flex items-center gap-2">
                      <FlashcardsIcon className="h-3.5 w-3.5" />
                      {t("review.mode.flashcardsLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "learn")}
                  >
                    <span className="flex items-center gap-2">
                      <LearnIcon className="h-3.5 w-3.5" />
                      {t("review.mode.learnLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "type")}
                  >
                    <span className="flex items-center gap-2">
                      <TypeIcon className="h-3.5 w-3.5" />
                      {t("review.mode.typeLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length === 0}
                    onClick={() => onReviewDeck(deck.id, "spell")}
                  >
                    <span className="flex items-center gap-2">
                      <SpellIcon className="h-3.5 w-3.5" />
                      {t("review.mode.spellLabel")}
                    </span>
                  </Button>
                  <Button
                    size="sm"
                    variant="outline"
                    disabled={deck.cards.length < 4}
                    title={deck.cards.length < 4 ? t("review.minCardsRequired", { count: 4 }) : undefined}
                    onClick={() => onReviewDeck(deck.id, "match")}
                  >
                    <span className="flex items-center gap-2">
                      <MatchIcon className="h-3.5 w-3.5" />
                      {t("review.mode.matchLabel")}
                    </span>
                  </Button>
                </div>
              </div>
              <div className="mt-3 flex flex-wrap items-center gap-4 ui-text-xs-muted">
                <span>
                  {t("deck.lastSyncedLabel", { timestamp: formatDateTime(deck.lastSyncedAt) })}
                </span>
              </div>
            </li>
            );
          })}
        </ul>
      )}
      <div className="pt-2 flex justify-center md:justify-end">
        <Button
          size="sm"
          variant="primary"
          onClick={onNewDeck}
          disabled={!onNewDeck}
        >
          {t("deck.newDeck")}
        </Button>
      </div>
    </div>
    <StreakHistoryModal
      open={isStreakHistoryOpen}
      onClose={() => setIsStreakHistoryOpen(false)}
      reviewActivity={reviewActivity}
      streakCount={streakCount}
    />
    </>
  );
};
