import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { useDeckStore } from "../decks/useDeckStore";
import { ResolvedThemePreference, ThemePreference } from "./types";
type ResolvedTheme = "light" | "dark";

type ThemeContextValue = {
  theme: ThemePreference;
  resolvedTheme: ResolvedTheme;
  setTheme: (theme: ThemePreference) => void;
};

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined);

const customThemes: ResolvedThemePreference[] = ["sunrise", "sunset"];
const darkThemes: ResolvedThemePreference[] = ["sunset"];

const getSystemTheme = (prefersDark: boolean): ResolvedThemePreference =>
  prefersDark ? "sunset" : "sunrise";

const applyDocumentTheme = (theme: ResolvedThemePreference) => {
  if (typeof document === "undefined") {
    return;
  }
  const root = document.documentElement;
  root.classList.toggle("dark", darkThemes.includes(theme));
  customThemes.forEach((name) => {
    root.classList.toggle(`theme-${name}`, theme === name);
  });
};

type ThemeProviderProps = {
  children: React.ReactNode;
};

export const ThemeProvider = ({ children }: ThemeProviderProps) => {
  const theme = useDeckStore((state) => state.preferences.theme);
  const setThemePreference = useDeckStore((state) => state.setThemePreference);
  const [systemPrefersDark, setSystemPrefersDark] = useState<boolean>(() => {
    if (typeof window === "undefined") return false;
    return window.matchMedia("(prefers-color-scheme: dark)").matches;
  });

  useEffect(() => {
    if (typeof window === "undefined") return undefined;
    const media = window.matchMedia("(prefers-color-scheme: dark)");
    const handleChange = (event: MediaQueryListEvent) => {
      setSystemPrefersDark(event.matches);
    };
    media.addEventListener("change", handleChange);
    return () => media.removeEventListener("change", handleChange);
  }, []);

  const resolvedThemeName: ResolvedThemePreference =
    theme === "system" ? getSystemTheme(systemPrefersDark) : theme;

  useEffect(() => {
    applyDocumentTheme(resolvedThemeName);
  }, [resolvedThemeName]);

  const value = useMemo<ThemeContextValue>(
    () => ({
      theme,
      resolvedTheme: darkThemes.includes(resolvedThemeName) ? "dark" : "light",
      setTheme: setThemePreference
    }),
    [theme, resolvedThemeName, setThemePreference]
  );

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>;
};

export const useTheme = () => {
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error("useTheme must be used within a ThemeProvider");
  }
  return context;
};
