import { useEffect, useRef } from "react";

type SessionLifecycleOptions = {
  isOpen: boolean;
  sessionVersion: number;
  onReset?: () => void;
  onStart?: () => void;
  canStart?: boolean;
};

export const useSessionLifecycle = ({
  isOpen,
  sessionVersion,
  onReset,
  onStart,
  canStart = true
}: SessionLifecycleOptions) => {
  const resetRef = useRef(onReset);
  const startRef = useRef(onStart);

  useEffect(() => {
    resetRef.current = onReset;
  }, [onReset]);

  useEffect(() => {
    startRef.current = onStart;
  }, [onStart]);

  useEffect(() => {
    if (!isOpen || sessionVersion === 0 || !canStart) {
      return;
    }
    resetRef.current?.();
    startRef.current?.();
  }, [isOpen, sessionVersion, canStart]);
};
