import clsx from "clsx";
import { Button } from "@ui/components/Button";
import { useTranslation } from "../i18n/I18nProvider";
import type { MatchGrid } from "./types";
import { formatMatchTime } from "./matchUtils";
import { useMemo } from "react";

type MatchBoardProps = {
  deckTitle?: string;
  grid: MatchGrid;
  setGrid: (grid: MatchGrid) => void;
  tiles: { key: string; text: string; matched: boolean; side: "front" | "back" }[];
  selected: number[];
  selectTile: (index: number) => void;
  mistakes: number;
  elapsedMs: number;
  completed: boolean;
  score: number;
  pairs: number;
  started: boolean;
  canStart: boolean;
  startGame: () => void;
  stopGame: () => void;
};

const pairPresets = [2, 4, 5, 6, 8, 10, 12, 15, 18];

export const MatchBoard = ({
  deckTitle,
  grid,
  setGrid,
  tiles,
  selected,
  selectTile,
  mistakes,
  elapsedMs,
  completed,
  score,
  pairs,
  started,
  canStart,
  startGame,
  stopGame
}: MatchBoardProps) => {
  const { t } = useTranslation();
  const showControlsPanel = !started || completed;
  const configuredPairs = Math.max(1, Math.floor((grid.rows * grid.cols) / 2));
  const displayPairs = started || completed ? pairs : configuredPairs;

  const shouldShowBoard = started && !completed;

  const columns = useMemo(() => {
    const front: Array<{ tile: MatchBoardProps["tiles"][number]; index: number }> = [];
    const back: Array<{ tile: MatchBoardProps["tiles"][number]; index: number }> = [];
    tiles.forEach((tile, index) => {
      if (tile.side === "front") {
        front.push({ tile, index });
      } else {
        back.push({ tile, index });
      }
    });
    return { front, back };
  }, [tiles]);

  // Build status text without nested ternaries for readability
  const statusText = useMemo(() => {
    if (completed) {
      return t("review.match.summary", {
        pairs,
        time: formatMatchTime(elapsedMs),
        mistakes,
        score
      });
    }

    if (canStart) {
      return null;
    }

    return t("review.emptyDeck");
  }, [completed, pairs, elapsedMs, mistakes, score, canStart, t]);

  const renderColumn = (
    label: string,
    dataset: Array<{ tile: MatchBoardProps["tiles"][number]; index: number }>
  ) => (
    <div className="ui-match-column">
      <p className="ui-match-column-label">{label}</p>
      <div className="ui-match-column-stack">
        {dataset.map(({ tile, index }) => {
          const isSelected = selected.includes(index);
          return (
            <button
              key={tile.key}
              type="button"
              onClick={() => selectTile(index)}
              className={clsx(
                "ui-match-tile",
                tile.side === "front" ? "is-front" : "is-back",
                isSelected && "is-selected",
                tile.matched && "is-matched"
              )}
            >
              <span className="ui-match-text">
                {tile.text}
              </span>
            </button>
          );
        })}
      </div>
    </div>
  );

  // Pre-render board or status to avoid large inline ?: blocks in JSX
  const boardContent = shouldShowBoard ? (
    <div className="ui-match-columns">
      {renderColumn(t("review.match.columnFront"), columns.front)}
      {renderColumn(t("review.match.columnBack"), columns.back)}
    </div>
  ) : statusText ? (
    <div className="ui-empty-panel">
      {statusText}
    </div>
  ) : '';

  return (
    <div className="space-y-4">
      {shouldShowBoard && (
        <div className="flex flex-wrap items-center justify-between gap-3">
          <div className="flex items-center gap-2 text-sm text-slate-800 dark:text-slate-300">
            <span className="font-medium text-slate-700 dark:text-slate-300">{deckTitle}</span>
            <span aria-hidden>·</span>
            <span>{t("review.match.time")}:&nbsp;<strong>{formatMatchTime(elapsedMs)}</strong></span>
            <span aria-hidden>·</span>
            <span>{t("review.match.mistakes")}:&nbsp;<strong>{mistakes}</strong></span>
            <span aria-hidden>·</span>
            <span>{t("review.match.pairsCount", { count: displayPairs })}</span>
            {completed && (
              <>
                <span aria-hidden>·</span>
                <span>{t("review.match.score")}:&nbsp;<strong>{score}</strong></span>
              </>
            )}
          </div>
          {started && !completed && (
            <Button
              size="sm"
              variant="outline"
              onClick={stopGame}
            >
              {t("review.match.stop")}
            </Button>
          )}
        </div>
      )}

      <p className="ui-text-xs-muted">{t("review.match.instruction")}</p>

      {showControlsPanel && (
        <div className="ui-surface-panel text-sm">
          <span className="ui-kicker">
            {t("review.match.selectSize")}
          </span>
          <div className="ui-match-preset-grid">
            {pairPresets.map((pairCount) => {
              const active = pairCount === configuredPairs;
              return (
                <Button
                  key={`pairs-${pairCount}`}
                  size="sm"
                  variant={active ? "secondary" : "outline"}
                  className={clsx(
                    active && "ui-btn-emerald-soft"
                  )}
                  onClick={() => setGrid({ rows: pairCount, cols: 2 })}
                >
                  {t("review.match.pairsCount", { count: pairCount })}
                </Button>
              );
            })}
          </div>
          <div className="ui-match-action-row">
            <Button
              size="sm"
              variant="secondary"
              className="ui-btn-emerald-soft"
              onClick={startGame}
              disabled={!canStart}
            >
              {t("review.match.start")}
            </Button>
            {started && !completed && (
              <Button
                size="sm"
                variant="outline"
                onClick={stopGame}
              >
                {t("review.match.stop")}
              </Button>
            )}
          </div>
        </div>
      )}

      {boardContent}

    </div>
  );
};
