import { format } from "date-fns";
import { DeckSyncConflict } from "./useDeckStore";
import { useTranslation } from "../i18n/I18nProvider";
import { Button } from "@ui/components/Button";
import { GlassModal } from "@ui/components/GlassModal";

type SyncConflictsDialogProps = {
  conflicts: DeckSyncConflict[];
  onResolve: (deckId: string, resolution: "local" | "remote") => void;
  onDismiss: () => void;
};

const formatDateTime = (date: Date | undefined) =>
  date ? format(date, "PPpp") : "Unknown";

export const SyncConflictsDialog = ({
  conflicts,
  onResolve,
  onDismiss
}: SyncConflictsDialogProps) => {
  if (conflicts.length === 0) {
    return null;
  }

  const { t } = useTranslation();

  return (
    <GlassModal
      open={conflicts.length > 0}
      onClose={onDismiss}
      panelClassName="ui-dialog-lg"
      contentClassName="text-slate-900 dark:text-slate-50"
    >
      <div className="flex items-center justify-between gap-4">
        <h3 className="ui-title-lg">{t("deck.conflictsTitle")}</h3>
      </div>
      <p className="mt-2 ui-text-sm-muted">
        {t("deck.conflictsSubtitle", { count: conflicts.length })}
      </p>
      <div className="mt-6 space-y-6">
        {conflicts.map((conflict) => (
          <div key={conflict.deckId} className="ui-surface-panel">
            <div className="flex flex-wrap items-start justify-between gap-4">
              <div>
                <h4 className="ui-title-base">
                  {conflict.local.title}
                </h4>
                <p className="ui-text-xs-muted">
                  {t("deck.deckIdLabel", { id: conflict.deckId })}
                </p>
              </div>
              <div className="flex gap-2">
                <Button
                  type="button"
                  size="sm"
                  variant="primary"
                  onClick={() => onResolve(conflict.deckId, "local")}
                >
                  {t("deck.keepLocal")}
                </Button>
                <Button
                  type="button"
                  size="sm"
                  variant="outline"
                  onClick={() => onResolve(conflict.deckId, "remote")}
                >
                  {t("deck.keepRemote")}
                </Button>
              </div>
            </div>
            <div className="mt-4 grid gap-4 text-xs text-slate-600 dark:text-slate-300 md:grid-cols-2">
              <div className="ui-surface-panel ui-surface-panel-sm">
                <h5 className="ui-title-sm">
                  {t("deck.conflictLocal")}
                </h5>
                <p className="mt-1 ui-text-sm-muted">
                  {t("deck.updatedLabel", { timestamp: formatDateTime(conflict.local.updatedAt) })}
                </p>
                <p className="mt-1 ui-text-sm-muted">
                  {t("deck.cardCountLabel", { count: conflict.local.cards.length })}
                </p>
              </div>
              <div className="ui-surface-panel ui-surface-panel-sm">
                <h5 className="ui-title-sm">
                  {t("deck.conflictRemote")}
                </h5>
                <p className="mt-1 ui-text-sm-muted">
                  {t("deck.updatedLabel", { timestamp: formatDateTime(conflict.remote.updatedAt) })}
                </p>
                <p className="mt-1 ui-text-sm-muted">
                  {t("deck.cardCountLabel", { count: conflict.remote.cards.length })}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>
    </GlassModal>
  );
};
