import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import ReactDOM from "react-dom/client";
import { useGoogleDriveLogin } from "./auth/useGoogleDriveLogin";
import { I18nProvider, useTranslation } from "./i18n/I18nProvider";
import { DeckManager } from "./decks/DeckManager";
import { useDeckSync } from "./decks/useDeckSync";
import { SyncConflictsDialog } from "./decks/SyncConflictsDialog";
import { useDeckStore } from "./decks/useDeckStore";
import { DeckFormModal } from "./decks/DeckFormModal";
import { AppHeader } from "./components/AppHeader";
import { ExternalLinkIcon } from "./components/icons";
import { DeckReviewModal } from "./review/DeckReviewModal";
import { ReviewMode } from "./review/types";
import { ThemeProvider } from "./theme/ThemeProvider";
import { LocaleSwitcher } from "./i18n/LocaleSwitcher";
import {
  acquireDriveLock,
  refreshDriveLock,
  releaseDriveLock,
  LOCK_REFRESH_INTERVAL_MS
} from "./decks/sync/driveLock";
import { Button } from "@ui/components/Button";
import { GrowlProvider } from "@ui/components/Growl";
import "./styles/global.css";

type DriveLockState =
  | { status: "idle" }
  | { status: "acquiring" }
  | { status: "acquired"; expiresAt: Date }
  | { status: "blocked"; expiresAt?: Date; ownerId?: string }
  | { status: "error"; message: string };

const DRIVE_LOCK_OWNER_KEY = "nova-drive-lock-owner";

const generateLockOwnerId = () => {
  const createRandomId = () => {
    const randomUUID = typeof globalThis.crypto?.randomUUID === "function";
    if (randomUUID) {
      return globalThis.crypto.randomUUID();
    }
    return `${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 10)}`;
  };

  if (typeof window === "undefined") {
    return createRandomId();
  }

  try {
    const existing = window.sessionStorage.getItem(DRIVE_LOCK_OWNER_KEY);
    if (existing) {
      return existing;
    }
    const generated = createRandomId();
    window.sessionStorage.setItem(DRIVE_LOCK_OWNER_KEY, generated);
    return generated;
  } catch (error) {
    console.warn("Unable to access sessionStorage for lock owner id", error);
    return createRandomId();
  }
};

const getOrCreateLockOwnerId = () => generateLockOwnerId();

const AppContent = () => {
  const { t } = useTranslation();
  const { login, signOut, status, accessToken, expiresAt } =
    useGoogleDriveLogin();
  const {
    pullFromDrive,
    pushLocalChanges,
    conflicts,
    resolveConflict,
    dismissConflicts,
    syncStatus,
    syncError
  } = useDeckSync();
  const decks = useDeckStore((state) => state.decks);
  const hasLocalChanges = useDeckStore((state) => state.hasLocalChanges);

  const hasValidToken = Boolean(accessToken) && (!expiresAt || expiresAt > Date.now());
  const isAuthenticated = Boolean(hasValidToken);
  const isAuthLoading = status === "loading";
  const [initialSyncDone, setInitialSyncDone] = useState(false);

  const handleSignIn = useCallback(() => {
    void login();
  }, [login]);

  const handleResolveConflict = useCallback(
    (deckId: string, resolution: "local" | "remote") => {
      if (!accessToken) {
        return;
      }
      void resolveConflict(deckId, resolution, accessToken);
    },
    [accessToken, resolveConflict]
  );

  const [driveLockState, setDriveLockState] = useState<DriveLockState>({ status: "idle" });
  const driveLockStatusRef = useRef<DriveLockState["status"]>("idle");

  const latestSyncedAt = useMemo(() => {
    const timestamps = decks
      .map((deck) => deck.lastSyncedAt?.getTime() ?? 0)
      .filter((value) => value > 0);
    if (timestamps.length === 0) {
      return undefined;
    }
    return new Date(Math.max(...timestamps));
  }, [decks]);

  const lastSyncedLabel = useMemo(() => {
    if (!latestSyncedAt) {
      return undefined;
    }
    return new Intl.DateTimeFormat(undefined, {
      dateStyle: "medium",
      timeStyle: "short"
    }).format(latestSyncedAt);
  }, [latestSyncedAt]);

  const [deckModalState, setDeckModalState] = useState<
    | { mode: "create" }
    | { mode: "edit"; deckId: string }
    | null
  >(null);
  const [reviewModalState, setReviewModalState] = useState<{
    deckId: string;
    mode: ReviewMode;
  } | null>(null);

  const isSyncPaused =
    deckModalState !== null ||
    reviewModalState !== null ||
    (isAuthenticated && driveLockState.status !== "acquired");

  const lockOwnerIdRef = useRef<string>(getOrCreateLockOwnerId());
  const lockFileIdRef = useRef<string | null>(null);
  const lockRefreshIntervalRef = useRef<number>();
  const lockRetryTimeoutRef = useRef<number>();

  const latestAccessTokenRef = useRef<string | null>(null);
  const syncStatusRef = useRef(syncStatus);
  const conflictsCountRef = useRef(conflicts.length);
  const syncPausedRef = useRef(isSyncPaused);
  const deckSyncTimeoutRef = useRef<number>();
  const lastSyncAtRef = useRef<number>(0);
  const syncInFlightRef = useRef(false);
  const hasPendingChangesRef = useRef(hasLocalChanges);

  const clearLockRefreshInterval = useCallback(() => {
    if (lockRefreshIntervalRef.current) {
      window.clearInterval(lockRefreshIntervalRef.current);
      lockRefreshIntervalRef.current = undefined;
    }
  }, []);

  const clearLockRetryTimeout = useCallback(() => {
    if (lockRetryTimeoutRef.current) {
      window.clearTimeout(lockRetryTimeoutRef.current);
      lockRetryTimeoutRef.current = undefined;
    }
  }, []);

  const handleSignOut = useCallback(() => {
    clearLockRetryTimeout();
    clearLockRefreshInterval();
    if (accessToken && lockFileIdRef.current) {
      void releaseDriveLock({
        accessToken,
        ownerId: lockOwnerIdRef.current,
        fileId: lockFileIdRef.current
      });
      lockFileIdRef.current = null;
    }
    setDriveLockState({ status: "idle" });
    setInitialSyncDone(false);
    signOut();
  }, [accessToken, clearLockRefreshInterval, clearLockRetryTimeout, signOut]);

  const requestSync = useCallback(
    async ({ force }: { force?: boolean } = {}) => {
      const token = latestAccessTokenRef.current;
      if (!token) {
        return;
      }
      if (conflictsCountRef.current > 0) {
        return;
      }
      if (!force && !hasPendingChangesRef.current) {
        return;
      }
      if (syncInFlightRef.current) {
        return;
      }
      const now = Date.now();
      if (!force && now - lastSyncAtRef.current < 60_000) {
        return;
      }
      syncInFlightRef.current = true;
      try {
        const pushed = await pushLocalChanges(token);
        if (pushed) {
          lastSyncAtRef.current = Date.now();
          hasPendingChangesRef.current = false;
        }
      } finally {
        syncInFlightRef.current = false;
      }
    },
    [pushLocalChanges]
  );

  const acquireLock = useCallback(
    async ({ force }: { force?: boolean } = {}) => {
      if (!accessToken || !isAuthenticated) {
        return;
      }
      if (driveLockStatusRef.current === "acquired" && !force) {
        return;
      }
      setDriveLockState({ status: "acquiring" });
      try {
        const result = await acquireDriveLock({
          accessToken,
          ownerId: lockOwnerIdRef.current,
          force: Boolean(force)
        });
        clearLockRetryTimeout();
        if (result.status === "acquired") {
          lockFileIdRef.current = result.fileId;
          setDriveLockState({ status: "acquired", expiresAt: result.expiresAt });
          await pullFromDrive(accessToken);
          setInitialSyncDone(true);
        } else {
          lockFileIdRef.current = result.fileId;
          setDriveLockState({
            status: "blocked",
            ...(result.expiresAt ? { expiresAt: result.expiresAt } : {}),
            ...(result.ownerId ? { ownerId: result.ownerId } : {})
          });
          setInitialSyncDone(false);
          const waitMs = Math.max(
            result.expiresAt ? result.expiresAt.getTime() - Date.now() + 1000 : 5000,
            5000
          );
          lockRetryTimeoutRef.current = window.setTimeout(() => {
            lockRetryTimeoutRef.current = undefined;
            void acquireLock({ force: true });
          }, waitMs);
        }
      } catch (error) {
        console.error("Failed to acquire Drive lock", error);
        setDriveLockState({
          status: "error",
          message: error instanceof Error ? error.message : String(error)
        });
        clearLockRetryTimeout();
        lockRetryTimeoutRef.current = window.setTimeout(() => {
          lockRetryTimeoutRef.current = undefined;
          void acquireLock({ force: true });
        }, 5000);
      }
    },
    [accessToken, isAuthenticated, clearLockRetryTimeout, pullFromDrive]
  );

  const handleRetryLock = useCallback(() => {
    clearLockRetryTimeout();
    void acquireLock();
  }, [acquireLock, clearLockRetryTimeout]);

  const handleForceLock = useCallback(() => {
    clearLockRetryTimeout();
    void acquireLock({ force: true });
  }, [acquireLock, clearLockRetryTimeout]);

  const refreshLock = useCallback(async () => {
    const token = latestAccessTokenRef.current;
    const fileId = lockFileIdRef.current;
    if (!token || !fileId) {
      return;
    }
    try {
      const result = await refreshDriveLock({
        accessToken: token,
        ownerId: lockOwnerIdRef.current,
        fileId
      });
      if (result.status === "ok") {
        setDriveLockState({ status: "acquired", expiresAt: result.expiresAt });
      } else {
        lockFileIdRef.current = null;
        setDriveLockState({
          status: "blocked",
          ...(result.expiresAt ? { expiresAt: result.expiresAt } : {}),
          ...(result.ownerId ? { ownerId: result.ownerId } : {})
        });
        setInitialSyncDone(false);
        clearLockRetryTimeout();
        const delay = Math.max(
          result.expiresAt ? result.expiresAt.getTime() - Date.now() + 1000 : 5000,
          5000
        );
        lockRetryTimeoutRef.current = window.setTimeout(() => {
          lockRetryTimeoutRef.current = undefined;
          void acquireLock({ force: true });
        }, delay);
      }
    } catch (error) {
      console.error("Failed to refresh Drive lock", error);
      setDriveLockState({
        status: "error",
        message: error instanceof Error ? error.message : String(error)
      });
      clearLockRetryTimeout();
      lockRetryTimeoutRef.current = window.setTimeout(() => {
        lockRetryTimeoutRef.current = undefined;
        void acquireLock({ force: true });
      }, 5000);
    }
  }, [acquireLock, clearLockRetryTimeout]);

  useEffect(() => {
    const previous = latestAccessTokenRef.current;
    latestAccessTokenRef.current = accessToken ?? null;
    if (!accessToken && previous && lockFileIdRef.current) {
      void releaseDriveLock({
        accessToken: previous,
        ownerId: lockOwnerIdRef.current,
        fileId: lockFileIdRef.current
      });
      lockFileIdRef.current = null;
      setDriveLockState({ status: "idle" });
      setInitialSyncDone(false);
    }
  }, [accessToken]);

  useEffect(() => {
    syncStatusRef.current = syncStatus;
  }, [syncStatus]);

  useEffect(() => {
    conflictsCountRef.current = conflicts.length;
  }, [conflicts.length]);

  useEffect(() => {
    driveLockStatusRef.current = driveLockState.status;
  }, [driveLockState.status]);

  useEffect(() => {
    hasPendingChangesRef.current = hasLocalChanges;
  }, [hasLocalChanges]);

  useEffect(() => {
    if (!isAuthenticated || !accessToken) {
      clearLockRetryTimeout();
      clearLockRefreshInterval();
      setInitialSyncDone(false);
      return;
    }
    void acquireLock({ force: true });
    return () => {
      clearLockRetryTimeout();
      clearLockRefreshInterval();
    };
  }, [
    isAuthenticated,
    accessToken,
    acquireLock,
    clearLockRetryTimeout,
    clearLockRefreshInterval
  ]);

  useEffect(() => {
    syncPausedRef.current = isSyncPaused;
  }, [isSyncPaused]);

  useEffect(() => {
    if (!accessToken || conflicts.length > 0 || isSyncPaused) {
      return;
    }
    if (!hasLocalChanges || syncStatus === "syncing") {
      return;
    }

    if (deckSyncTimeoutRef.current) {
      window.clearTimeout(deckSyncTimeoutRef.current);
    }

    deckSyncTimeoutRef.current = window.setTimeout(() => {
      deckSyncTimeoutRef.current = undefined;
      if (conflictsCountRef.current > 0 || syncPausedRef.current) {
        return;
      }
      void requestSync();
    }, 1200);

    return () => {
      if (deckSyncTimeoutRef.current) {
        window.clearTimeout(deckSyncTimeoutRef.current);
        deckSyncTimeoutRef.current = undefined;
      }
    };
  }, [accessToken, conflicts.length, hasLocalChanges, syncStatus, requestSync, isSyncPaused]);

  useEffect(() => {
    clearLockRefreshInterval();
    if (driveLockState.status !== "acquired") {
      return;
    }
    const intervalId = window.setInterval(() => {
      void refreshLock();
      if (!hasPendingChangesRef.current) {
        return;
      }
      void requestSync();
    }, LOCK_REFRESH_INTERVAL_MS);
    lockRefreshIntervalRef.current = intervalId;
    return () => {
      clearLockRefreshInterval();
    };
  }, [driveLockState.status, refreshLock, clearLockRefreshInterval, requestSync]);

  useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState === "visible" && driveLockState.status === "acquired") {
        void refreshLock();
      }
    };
    document.addEventListener("visibilitychange", handleVisibility);
    return () => document.removeEventListener("visibilitychange", handleVisibility);
  }, [driveLockState.status, refreshLock]);

  useEffect(() => {
    return () => {
      clearLockRetryTimeout();
      clearLockRefreshInterval();
      const token = latestAccessTokenRef.current;
      if (token && lockFileIdRef.current) {
        void releaseDriveLock({
          accessToken: token,
          ownerId: lockOwnerIdRef.current,
          fileId: lockFileIdRef.current
        });
      }
    };
  }, [clearLockRefreshInterval, clearLockRetryTimeout]);

  const deckModalDeck = useDeckStore((state) => {
    if (deckModalState?.mode === "edit") {
      return state.decks.find((item) => item.id === deckModalState.deckId);
    }
    return undefined;
  });

  const openCreateModal = useCallback(() => {
    setDeckModalState({ mode: "create" });
  }, []);

  const openEditModal = useCallback((deckId: string) => {
    setDeckModalState({ mode: "edit", deckId });
  }, []);

  const closeDeckModal = useCallback(() => {
    setDeckModalState(null);
  }, []);

  const currentYear = new Date().getFullYear();

  return (
    <div className="ui-page">
      <AppHeader
        isAuthenticated={isAuthenticated}
        isAuthLoading={isAuthLoading}
        onSignIn={handleSignIn}
        onSignOut={handleSignOut}
      />
      <main className="ui-container-main-lg flex-1">
        <div className="ui-vstack-10">
          <DeckManager
            isAuthenticated={isAuthenticated}
            syncStatus={syncStatus}
            {...(syncStatus === "error" && syncError ? { syncError } : {})}
            {...(lastSyncedLabel ? { lastSyncedLabel } : {})}
            lockStatus={driveLockState.status}
            onEditDeck={openEditModal}
            onReviewDeck={(deckId, mode) => setReviewModalState({ deckId, mode })}
            onNewDeck={openCreateModal}
          />
        </div>
      </main>
      {conflicts.length > 0 && (
        <SyncConflictsDialog
          conflicts={conflicts}
          onResolve={handleResolveConflict}
          onDismiss={dismissConflicts}
        />
      )}
      <DeckFormModal
        isOpen={deckModalState !== null}
        mode={deckModalState?.mode ?? "create"}
        {...(deckModalState?.mode === "edit" && deckModalDeck ? { deck: deckModalDeck } : {})}
        onClose={closeDeckModal}
      />
      <DeckReviewModal
        isOpen={reviewModalState !== null}
        {...(reviewModalState ? { deckId: reviewModalState.deckId } : {})}
        mode={reviewModalState?.mode ?? "flashcards"}
        onClose={() => setReviewModalState(null)}
      />
      <footer className="ui-footer ui-blur-bar">
        <div className="ui-container-wide ui-text-xs-muted ui-row-between">
          <span>
            © {currentYear}{" "}
            <a
              href="http://uavn.github.io/movanova"
              target="_blank"
              rel="noopener noreferrer"
              className="ui-footer-link inline-flex items-center gap-1"
            >
              {t("common.appName")}
              <ExternalLinkIcon className="h-3.5 w-3.5" aria-hidden="true" />
            </a>
          </span>
          <span>
            <a
              href="https://github.com/uavn"
              target="_blank"
              rel="noopener noreferrer"
              className="ui-footer-link inline-flex items-center gap-1"
            >
              {t("common.footerNote")}
              <ExternalLinkIcon className="h-3.5 w-3.5" aria-hidden="true" />
            </a>
          </span>
          <LocaleSwitcher className="justify-end" />
        </div>
      </footer>
      {(driveLockState.status === "blocked" || driveLockState.status === "error") && (
        <div className="ui-overlay ui-overlay-dark z-[70] text-center">
          <div className="ui-dialog ui-dialog-dark ui-vstack-4">
            <h2 className="ui-title-lg">
              {driveLockState.status === "blocked" ? t("drive.lockedTitle") : t("drive.lockErrorTitle")}
            </h2>
            <p className="ui-text-sm-muted">
              {driveLockState.status === "blocked"
                ? t("drive.lockedDescription")
                : t("drive.lockErrorDescription", {
                    message: driveLockState.status === "error" && driveLockState.message ? driveLockState.message : ""
                  })}
            </p>
            <div className="flex justify-center gap-3 flex-wrap">
              <Button variant="secondary" onClick={handleRetryLock}>
                {t("drive.lockRetry")}
              </Button>
              <Button onClick={handleForceLock}>
                {t("drive.lockForce")}
              </Button>
              <Button variant="ghost" onClick={handleSignOut}>
                {t("common.signOut")}
              </Button>
            </div>
          </div>
        </div>
      )}
      {(isAuthLoading || (isAuthenticated && !initialSyncDone && driveLockState.status !== "blocked")) && (
        <div className="ui-overlay ui-overlay-dark z-40">
          <div className="ui-vstack-3 text-center">
            <p className="ui-text-sm-muted uppercase tracking-wide">
              {isAuthLoading ? t("common.loading") : t("drive.syncing")}
            </p>
            <p className="ui-title-lg">{t("deck.workspaceTitle")}</p>
            <div className="flex justify-center gap-3 flex-wrap">
              {!isAuthLoading && (
                <Button variant="secondary" onClick={() => window.location.reload()}>
                  {t("common.reload")}
                </Button>
              )}
              <Button variant="ghost" onClick={handleSignOut}>
                {t("common.signOut")}
              </Button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const App = () => (
  <ThemeProvider>
    <I18nProvider>
      <GrowlProvider>
        <AppContent />
      </GrowlProvider>
    </I18nProvider>
  </ThemeProvider>
);

const rootElement = document.getElementById("root");
if (!rootElement) {
  throw new Error("Root element not found");
}
const root = ReactDOM.createRoot(rootElement);

console.info("[App] Initializing Nova Mova");

root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);
