import type { MouseEvent, ReactNode } from "react";
import { useEffect } from "react";
import { createPortal } from "react-dom";
import clsx from "clsx";
import { GlassPanel } from "./GlassPanel";

type GlassModalProps = {
  open: boolean;
  onClose: () => void;
  children: ReactNode;
  className?: string;
  overlayClassName?: string;
  panelClassName?: string;
  closeOnOverlay?: boolean;
  contentClassName?: string;
  showCloseButton?: boolean;
  closeAriaLabel?: string;
  closeButtonClassName?: string;
};

let modalLockCount = 0;
let prevBodyOverflow: string | undefined;
let prevHtmlOverflow: string | undefined;

const lockScroll = () => {
  if (typeof document === "undefined") return;
  const body = document.body;
  const html = document.documentElement;
  if (modalLockCount === 0) {
    prevBodyOverflow = body.style.overflow || getComputedStyle(body).overflow || "";
    prevHtmlOverflow = html.style.overflow || getComputedStyle(html).overflow || "";
    body.style.overflow = "hidden";
    html.style.overflow = "hidden";
    body.classList.add("glass-modal-open");
    html.classList.add("glass-modal-open");
  }
  modalLockCount += 1;
};

const unlockScroll = () => {
  if (typeof document === "undefined") return;
  const body = document.body;
  const html = document.documentElement;
  modalLockCount = Math.max(0, modalLockCount - 1);
  if (modalLockCount === 0) {
    body.style.overflow = prevBodyOverflow ?? "";
    html.style.overflow = prevHtmlOverflow ?? "";
    body.classList.remove("glass-modal-open");
    html.classList.remove("glass-modal-open");
    prevBodyOverflow = undefined;
    prevHtmlOverflow = undefined;
  }
};

export const GlassModal = ({
  open,
  onClose,
  children,
  className,
  overlayClassName,
  panelClassName,
  closeOnOverlay = true,
  contentClassName,
  showCloseButton = true,
  closeAriaLabel,
  closeButtonClassName
}: GlassModalProps) => {
  useEffect(() => {
    if (!open) {
      unlockScroll();
      return;
    }

    lockScroll();
    return () => unlockScroll();
  }, [open]);

  if (!open) {
    return null;
  }

  const handleOverlayClick = () => {
    if (closeOnOverlay) {
      onClose();
    }
  };

  const stopPropagation = (event: MouseEvent) => {
    event.stopPropagation();
  };

  const modalContent = (
    <div
      className={clsx(
        "fixed inset-0 z-[999] flex items-stretch justify-center overflow-hidden bg-transparent px-0 py-0 backdrop-blur-md dark:bg-transparent md:items-start md:px-0 md:py-8",
        overlayClassName,
        className
      )}
      onClick={handleOverlayClick}
    >
      <GlassPanel
        className={clsx(
          "relative flex w-full flex-col overflow-hidden rounded-[16px] p-0 md:max-h-[calc(100vh-4rem)] md:max-w-4xl md:p-2",
          panelClassName
        )}
        onClick={stopPropagation}
      >
        {showCloseButton && (
          <button
            type="button"
            aria-label={closeAriaLabel ?? "Close"}
            onClick={onClose}
            style={{
              top: "max(0.75rem, env(safe-area-inset-top))",
              right: "max(0.5rem, env(safe-area-inset-right))"
            }}
            className={clsx(
              "absolute right-2 top-3 z-20 rounded-full border border-slate-200 bg-white/80 p-2 text-slate-600 shadow-sm transition hover:border-slate-400 hover:text-slate-900 dark:border-white/15 dark:bg-white/10 dark:text-slate-300",
              closeButtonClassName
            )}
          >
            <svg
              className="h-5 w-5 md:h-4 md:w-4"
              viewBox="0 0 20 20"
              fill="none"
              stroke="currentColor"
              strokeWidth="1.5"
            >
              <path strokeLinecap="round" strokeLinejoin="round" d="M6 6l8 8M14 6l-8 8" />
            </svg>
            <span className="sr-only">{closeAriaLabel ?? "Close"}</span>
          </button>
        )}
        <div
          className={clsx(
            "flex w-full flex-1 min-h-0 flex-col gap-2 overflow-auto overscroll-contain px-2.5 py-2.5 sm:px-6 sm:py-5 md:px-9 md:py-6 lg:px-12",
            contentClassName
          )}
        >
          {children}
        </div>
      </GlassPanel>
    </div>
  );

  if (typeof document === "undefined") {
    return modalContent;
  }
  return createPortal(modalContent, document.body);
};
