import { useMemo } from "react";
import clsx from "clsx";
import { GlassPanel } from "@ui/components/GlassPanel";
import { useTranslation } from "../i18n/I18nProvider";
import type { MatchResult } from "@core/models";
import { formatMatchTime } from "./matchUtils";
import type { MatchGrid } from "./types";

const getPairCount = (rows: number, cols: number) => Math.max(1, Math.floor((rows * cols) / 2));

type MatchHistoryProps = {
  results: MatchResult[];
  maxEntries?: number;
  highlightTimestamp?: number | null;
  grid: MatchGrid;
};

export const MatchHistory = ({
  results,
  maxEntries = 10,
  highlightTimestamp,
  grid
}: MatchHistoryProps) => {
  const { t } = useTranslation();
  const targetPairs = getPairCount(grid.rows, grid.cols);

  const [rows, formatter] = useMemo(() => {
    const filtered = results.filter((result) => {
      return getPairCount(result.rows, result.cols) === targetPairs;
    });
    const sorted = [...filtered].sort((a, b) => {
      const scoreDiff = b.score - a.score;
      if (scoreDiff !== 0) {
        return scoreDiff;
      }
      return b.completedAt.getTime() - a.completedAt.getTime();
    });
    const dateFormatter = new Intl.DateTimeFormat(undefined, {
      dateStyle: "medium",
      timeStyle: "short"
    });

    if (sorted.length <= maxEntries || !highlightTimestamp) {
      return [sorted.slice(0, Math.max(1, maxEntries)), dateFormatter] as const;
    }

    const baseLimit = Math.max(1, maxEntries - 1);
    const baseRows = sorted.slice(0, baseLimit);
    const highlightRow = sorted.find(
      (result) => result.completedAt.getTime() === highlightTimestamp
    );

    if (!highlightRow) {
      return [sorted.slice(0, Math.max(1, maxEntries)), dateFormatter] as const;
    }

    const alreadyIncluded = baseRows.some(
      (result) => result.completedAt.getTime() === highlightTimestamp
    );
    const combined = alreadyIncluded ? baseRows : [...baseRows, highlightRow];
    return [combined, dateFormatter] as const;
  }, [results, maxEntries, highlightTimestamp, targetPairs]);

  if (rows.length === 0) {
    return (
      <>
        <div className="p-3 text-sm text-slate-600 dark:text-slate-300 md:hidden">
          {t("review.match.historyEmpty")}
        </div>
        <GlassPanel className="hidden md:block p-6 text-sm text-slate-600 dark:text-slate-300">
          {t("review.match.historyEmpty")}
        </GlassPanel>
      </>
    );
  }

  const content = (
    <>
      <div>
        <p className="ui-kicker">
          {t("review.match.historyTitle")}
        </p>
      </div>
      <div className="overflow-x-auto">
        <table className="ui-table">
          <thead>
            <tr className="ui-th-row">
              <th className="ui-th">{t("review.match.historyTable.played")}</th>
              <th className="ui-th">{t("review.match.historyTable.time")}</th>
              <th className="ui-th">{t("review.match.historyTable.mistakes")}</th>
              <th className="ui-th text-right">
                {t("review.match.historyTable.score")}
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((result, index) => {
              const ts = result.completedAt.getTime();
              const isHighlighted = highlightTimestamp != null && ts === highlightTimestamp;
              const resultPairs = getPairCount(result.rows, result.cols);
              return (
                <tr
                  key={`${ts}-${index}`}
                  className={clsx("ui-tr", isHighlighted && "ui-tr-highlight")}
                >
                  <td className="ui-td">{formatter.format(result.completedAt)}</td>
                  <td className="ui-td">{formatMatchTime(result.timeMs)}</td>
                  <td className="ui-td">{result.mistakes}</td>
                  <td className="ui-td-right">
                    {result.score}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </>
  );

  return (
    <>
      <div className="ui-vstack-3 p-2 md:hidden">{content}</div>
      <GlassPanel className="hidden md:block ui-vstack-4 p-6">{content}</GlassPanel>
    </>
  );
};
