export const buildDemoDeck = (): DeckRecord => createDeckRecord(demoDeckTemplate);

const ensureDemoDeck = (state: DeckStoreState): DeckStoreState => {
  const demoBlocked = state.preferences?.demoDismissed;
  if (demoBlocked || state.decks.length > 0) {
    return state;
  }
  const demoDeck = buildDemoDeck();
  return {
    ...state,
    decks: [demoDeck],
    selectedDeckId: demoDeck.id,
    hasLocalChanges: true
  };
};

const formatDateKey = (date: Date) => date.toISOString().slice(0, 10);
const differenceInDays = (from: string, to: string) =>
  Math.floor((Date.parse(from) - Date.parse(to)) / 86400000);
const TWENTY_FOUR_HOURS_MS = 86_400_000;
const MAX_REVIEW_ACTIVITY_ENTRIES = 400;

const pruneReviewActivity = (activity: Record<string, number>) => {
  const entries = Object.entries(activity).filter(
    ([, value]) => typeof value === "number" && Number.isFinite(value) && value > 0
  );
  if (entries.length === 0) {
    return {};
  }
  entries.sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0));
  const trimmed = entries.slice(-MAX_REVIEW_ACTIVITY_ENTRIES);
  return trimmed.reduce<Record<string, number>>((acc, [key, value]) => {
    acc[key] = value;
    return acc;
  }, {});
};

const applyReviewActivityDelta = (
  activity: Record<string, number>,
  dayKey: string,
  delta: number,
  ensurePresence = false
) => {
  const previousValue = activity[dayKey] ?? 0;
  const nextValue =
    delta > 0
      ? previousValue + Math.max(0, delta)
      : ensurePresence && previousValue === 0
        ? 1
        : previousValue;
  if (nextValue === previousValue) {
    return activity;
  }
  const nextActivity = {
    ...activity,
    [dayKey]: nextValue
  };
  return pruneReviewActivity(nextActivity);
};

const calculateLevel = (xp: number) => Math.max(1, Math.floor(xp / 100) + 1);
const normalizeThemePreference = (value?: string | null): ThemePreference => {
  if (value === "dark") return "sunset";
  if (value === "light") return "sunrise";
  const allowed: ThemePreference[] = ["system", "sunrise", "sunset"];
  if (value && (allowed as string[]).includes(value)) {
    return value as ThemePreference;
  }
  return "system";
};

export type PendingDeckDeletion = {
  deckId: string;
  driveFileId: string;
};

export type DeckSyncMetadata = {
  driveFileId?: string;
  lastSyncedAt?: Date;
};

export type DeckSyncConflict = {
  deckId: string;
  driveFileId?: string;
  local: DeckRecord;
  remote: DeckRecord;
};

