export const useDeckStore = create<DeckStoreState>()(
  persist(
    (set, get) => ({
      ...ensureDemoDeck(defaultState),
      createDeck: ({ title, description, cards }) => {
        const deck = createDeckRecord({
          title,
          ...(description ? { description } : {}),
          cards
        });
        set((state) => ({
          decks: [...state.decks, deck],
          selectedDeckId: deck.id,
          syncStatus: "idle",
          syncError: undefined,
          hasLocalChanges: true,
          reviewState: {
            ...state.reviewState,
            [deck.id]: undefined
          }
        }));
        return deck.id;
      },
      addCardToDeck: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const card = createCard({ deckId, ...payload });
          const updatedDeck: DeckRecord = {
            ...deck,
            cards: [...deck.cards, card],
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      removeCardFromDeck: (deckId, cardId) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            cards: deck.cards.filter((card) => card.id !== cardId),
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      updateDeckDetails: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            ...payload,
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      deleteDeck: (deckId) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const filteredPending = state.pendingDeletions.filter((item) => item.deckId !== deckId);
          const pendingDeletions =
            deck.driveFileId != null
              ? [...filteredPending, { deckId, driveFileId: deck.driveFileId }]
              : filteredPending;
          return {
            ...state,
            decks: state.decks.filter((item) => item.id !== deckId),
            selectedDeckId: state.selectedDeckId === deckId ? undefined : state.selectedDeckId,
            hasLocalChanges: true,
            preferences: {
              ...state.preferences,
              demoDismissed: state.decks.length <= 1 ? true : state.preferences.demoDismissed
            },
            pendingDeletions,
            reviewState: Object.fromEntries(
              Object.entries(state.reviewState).filter(([id]) => id !== deckId)
            )
          };
        }),
      setDeckSyncMetadata: (deckId, metadata) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            driveFileId: metadata.driveFileId ?? deck.driveFileId,
            lastSyncedAt: metadata.lastSyncedAt ?? deck.lastSyncedAt
          };
          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item))
          };
        }),
      replaceDeck: (deck) =>
        set((state) => {
          const existing = state.decks.find((item) => item.id === deck.id);
          const decks = existing
            ? state.decks.map((item) => (item.id === deck.id ? deck : item))
            : [...state.decks, deck];

          let reviewState = state.reviewState;
          if (existing) {
            const keepReview =
              state.reviewState[deck.id] &&
              existing.cards.length === deck.cards.length &&
              existing.updatedAt.getTime() === deck.updatedAt.getTime();
            if (!keepReview) {
              reviewState = {
                ...state.reviewState,
                [deck.id]: undefined
              };
            }
          }

          return {
            ...state,
            decks,
            reviewState
          };
        }),
      updateDeckFromDraft: (deckId, payload) =>
        set((state) => {
          const deck = state.decks.find((item) => item.id === deckId);
          if (!deck) {
            return state;
          }

          const now = new Date();
          const existingCards = new Map(deck.cards.map((card) => [card.id, card]));

          const cards = payload.cards.map((cardInput) => {
            if (cardInput.id && existingCards.has(cardInput.id)) {
              const existing = existingCards.get(cardInput.id)!;
              return {
                ...existing,
                front: cardInput.front,
                back: cardInput.back,
                notes: cardInput.notes,
                updatedAt: now
              };
            }
            return createCard({
              deckId,
              front: cardInput.front,
              back: cardInput.back,
              ...(cardInput.notes ? { notes: cardInput.notes } : {})
            });
          });

          const dueCardCount = cards.reduce(
            (count, card) => (card.dueAt.getTime() <= now.getTime() ? count + 1 : count),
            0
          );

          const updatedDeck: DeckRecord = {
            ...deck,
            title: payload.title,
            description: payload.description,
            cards,
            updatedAt: now,
            version: deck.version + 1,
            dueCardCount,
            lastSyncedAt: deck.lastSyncedAt
          };

          return {
            ...state,
            decks: state.decks.map((item) => (item.id === deckId ? updatedDeck : item)),
            hasLocalChanges: true,
            reviewState: {
              ...state.reviewState,
              [deckId]: undefined
            }
          };
        }),
      setDeckReviewState: (deckId, reviewState) => {
        const now = new Date();
        const today = formatDateKey(now);
        const lastReviewDate = get().lastReviewDate;
        const lastReviewTimestamp = get().lastReviewTimestamp;
        const lastReviewInstant = lastReviewTimestamp ? new Date(lastReviewTimestamp) : undefined;
        const previousDeckState = get().reviewState[deckId];
        const isSessionStart = !previousDeckState && Boolean(reviewState);
        const previousIndex = previousDeckState?.currentIndex ?? 0;
        const nextIndex = reviewState?.currentIndex ?? previousIndex;
        const processedCards = Math.max(0, nextIndex - previousIndex);
        return set((state) => {
          const streakBonus = 1 + state.streakCount * 0.1;
          const xpGain =
            reviewState && processedCards > 0 ? Math.max(1, Math.round(processedCards * streakBonus)) : 0;
          const nextStreakCount = (() => {
            if (!isSessionStart) return state.streakCount;
            if (lastReviewInstant) {
              const sameDay = formatDateKey(lastReviewInstant) === today;
              if (sameDay) {
                return state.streakCount;
              }
              const diffMs = now.getTime() - lastReviewInstant.getTime();
              if (diffMs <= TWENTY_FOUR_HOURS_MS) {
                return state.streakCount + 1;
              }
              return 1;
            }
            if (!lastReviewDate) return 1;
            const dayDiff = differenceInDays(today, lastReviewDate);
            if (dayDiff === 0) return state.streakCount;
            if (dayDiff === 1) return state.streakCount + 1;
            return 1;
          })();
          const newXpTotal = state.xp + xpGain;
          const nextLevel = xpGain > 0 ? calculateLevel(newXpTotal) : state.level;
          let nextReviewActivity = state.reviewActivity;
          if (processedCards > 0) {
            nextReviewActivity = applyReviewActivityDelta(state.reviewActivity, today, processedCards);
          } else if (isSessionStart) {
            nextReviewActivity = applyReviewActivityDelta(state.reviewActivity, today, 0, true);
          }
          const nextLastReviewDate = isSessionStart ? today : state.lastReviewDate;
          const nextLastReviewTimestamp = isSessionStart ? now.toISOString() : state.lastReviewTimestamp;

          return {
            ...state,
            reviewState: {
              ...state.reviewState,
              [deckId]: reviewState
                ? {
                    ...reviewState,
                    statusMap: reviewState.statusMap ?? {},
                    lastUpdatedAt: (reviewState.lastUpdatedAt ?? new Date()).toISOString()
                  }
                : undefined
            },
            streakCount: nextStreakCount,
            lastReviewDate: nextLastReviewDate,
            lastReviewTimestamp: nextLastReviewTimestamp,
            xp: newXpTotal,
            level: nextLevel,
            reviewActivity: nextReviewActivity,
            preferences: {
              ...state.preferences,
              stats: {
                streakCount: nextStreakCount,
                lastReviewDate: nextLastReviewDate,
                lastReviewTimestamp: nextLastReviewTimestamp,
                reviewActivity: nextReviewActivity,
                xp: newXpTotal,
                level: nextLevel
              }
            }
          };
        });
      },
      markSyncStatus: (status, error) =>
        set(() => ({
          syncStatus: status,
          syncError: error
        })),
      setConflicts: (conflicts) =>
        set(() => ({
          conflicts
        })),
      clearConflicts: () =>
        set(() => ({
          conflicts: []
        })),
      setLocalChanges: (flag) =>
        set((state) => ({
          hasLocalChanges: flag ? true : state.pendingDeletions.length > 0 ? true : false
        })),
      setThemePreference: (theme) =>
        set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            theme: normalizeThemePreference(theme)
          },
          hasLocalChanges: true
        })),
      setLocalePreference: (locale) =>
        set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            locale
          },
          hasLocalChanges: true
        })),
      setPreferences: (preferences) => {
        const normalizedReviewActivity = preferences.stats?.reviewActivity
          ? pruneReviewActivity(preferences.stats.reviewActivity)
          : undefined;
        const statsPayload = preferences.stats
          ? {
              ...preferences.stats,
              reviewActivity: normalizedReviewActivity
            }
          : undefined;
        return set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            locale: preferences.locale,
            theme: normalizeThemePreference(preferences.theme),
            stats: statsPayload ?? state.preferences.stats,
            aiApiKey: preferences.aiApiKey ?? state.preferences.aiApiKey,
            demoDismissed: preferences.demoDismissed ?? state.preferences.demoDismissed
          },
          streakCount: statsPayload?.streakCount ?? state.streakCount,
          lastReviewDate: statsPayload?.lastReviewDate ?? state.lastReviewDate,
          lastReviewTimestamp: statsPayload?.lastReviewTimestamp ?? state.lastReviewTimestamp,
          xp: statsPayload?.xp ?? state.xp,
          level: statsPayload?.level ?? state.level,
          reviewActivity: statsPayload?.reviewActivity ?? state.reviewActivity
        }));
      },
      setAiApiKey: (key) =>
        set((state) => ({
          ...state,
          preferences: {
            ...state.preferences,
            aiApiKey: key
          },
          hasLocalChanges: true
        })),
      addMatchResult: (deckId, result) =>
        set((state) => {
          const deck = state.decks.find((d) => d.id === deckId);
          if (!deck) {
            return state;
          }
          const updatedDeck: DeckRecord = {
            ...deck,
            matchResults: [...(deck.matchResults ?? []), result],
            updatedAt: new Date(),
            version: deck.version + 1
          };
          return {
            ...state,
            decks: state.decks.map((d) => (d.id === deckId ? updatedDeck : d)),
            hasLocalChanges: true
          };
        }),
      removePendingDeletions: (deckIds) =>
        set((state) => ({
          ...state,
          pendingDeletions: state.pendingDeletions.filter(
            (item) => !deckIds.includes(item.deckId)
          )
        })),
      recordCardResult: (deckId, cardId, correct) =>
        set((state) => {
          if (!deckId || !cardId) {
            return state;
          }
          const deckStats = state.cardStats[deckId] ?? {};
          const cardStats = deckStats[cardId] ?? { correct: 0, incorrect: 0 };
          const updatedDeckStats = {
            ...deckStats,
            [cardId]: {
              correct: cardStats.correct + (correct ? 1 : 0),
              incorrect: cardStats.incorrect + (correct ? 0 : 1)
            }
          };
          return {
            ...state,
            cardStats: {
              ...state.cardStats,
              [deckId]: updatedDeckStats
            }
          };
        }),
      resetDeckStats: (deckId) =>
        set((state) => ({
          ...state,
          cardStats: {
            ...state.cardStats,
            [deckId]: {}
          }
        }))
    }),
    {
      name: STORAGE_KEY,
      storage:
        typeof window !== "undefined"
          ? createJSONStorage(() => window.localStorage)
          : undefined,
      version: 3,
      migrate: (persistedState, version) => {
        if (!persistedState) {
          return persistedState as PersistedState | undefined;
        }
        if (version < 2) {
          const data = persistedState as PersistedState;
          if (data.preferences) {
            const themeValue = (data.preferences as any).theme;
            data.preferences = {
              ...data.preferences,
              theme: normalizeThemePreference(themeValue)
            };
          }
        }
        if (version < 3) {
          const data = persistedState as PersistedState;
          if (data.preferences?.stats?.reviewActivity) {
            data.preferences.stats.reviewActivity = pruneReviewActivity(
              data.preferences.stats.reviewActivity
            );
          }
          if (data.reviewActivity) {
            data.reviewActivity = pruneReviewActivity(data.reviewActivity);
          }
        }
        return persistedState as PersistedState;
      },
      partialize: (state) => ({
        decks: state.decks.map(serializeDeck),
        reviewState: state.reviewState,
        preferences: state.preferences,
        pendingDeletions: state.pendingDeletions,
        streakCount: state.streakCount,
        lastReviewDate: state.lastReviewDate,
        lastReviewTimestamp: state.lastReviewTimestamp,
        xp: state.xp,
        level: state.level,
        reviewActivity: state.reviewActivity,
        cardStats: state.cardStats
      }),
      merge: (persistedState, currentState) => {
        const data = persistedState as PersistedState | undefined;
        if (!data?.decks) {
          return ensureDemoDeck(currentState);
        }

        const decks = data.decks.map(deserializeDeck);
        const reviewState = data.reviewState ?? {};

        const sanitizedReviewState: DeckStoreState["reviewState"] = {};
        decks.forEach((deck) => {
          const state = reviewState[deck.id];
          if (!state || !state.mode) {
            return;
          }
          const cardIds = new Set(deck.cards.map((card) => card.id));
          const isValid =
            state.cardOrder.every((cardId) => cardIds.has(cardId)) &&
            state.unknownCardIds.every((cardId) => cardIds.has(cardId));
          if (isValid) {
            sanitizedReviewState[deck.id] = {
              ...state,
              statusMap: state.statusMap ?? {}
            };
          }
        });

        const hasLocalChanges = decks.some((deck) => {
          if (!deck.lastSyncedAt) {
            return true;
          }
          return deck.updatedAt.getTime() > deck.lastSyncedAt.getTime();
        });

        const mergedPreferences =
          data.preferences != null
            ? {
                ...currentState.preferences,
                ...data.preferences,
                theme: normalizeThemePreference((data.preferences as any).theme),
                aiApiKey:
                  (data.preferences as AppPreferences).aiApiKey ??
                  currentState.preferences.aiApiKey
              }
            : currentState.preferences;

        return ensureDemoDeck({
          ...currentState,
          decks,
          reviewState: sanitizedReviewState,
          hasLocalChanges,
          preferences: mergedPreferences,
          pendingDeletions: data.pendingDeletions ?? currentState.pendingDeletions,
          streakCount: data.streakCount ?? currentState.streakCount,
          lastReviewDate: data.lastReviewDate ?? currentState.lastReviewDate,
          lastReviewTimestamp:
            data.lastReviewTimestamp ??
            data.preferences?.stats?.lastReviewTimestamp ??
            currentState.lastReviewTimestamp,
          xp: data.xp ?? data.preferences?.stats?.xp ?? currentState.xp,
          level: data.level ?? data.preferences?.stats?.level ?? currentState.level,
          reviewActivity: pruneReviewActivity(
            data.reviewActivity ??
              data.preferences?.stats?.reviewActivity ??
              currentState.reviewActivity ??
              {}
          ),
          cardStats: data.cardStats ?? currentState.cardStats
        });
      }
    }
  )
);
