import type { ReviewMode } from "./types";
import { FlashcardsReviewModal } from "./FlashcardsReviewModal";
import { LearnReviewModal } from "./LearnReviewModal";
import { TypeReviewModal } from "./TypeReviewModal";
import { MatchReviewModal } from "./MatchReviewModal";
import { SpellReviewModal } from "./SpellReviewModal";

type DeckReviewModalProps = {
  deckId?: string;
  mode: ReviewMode;
  isOpen: boolean;
  onClose: () => void;
};

const MIN_ADVANCED_CARDS = 4;

export const DeckReviewModal = ({ deckId, mode, isOpen, onClose }: DeckReviewModalProps) => {
  if (mode === "flashcards") {
    return <FlashcardsReviewModal deckId={deckId} isOpen={isOpen} onClose={onClose} />;
  }
  if (mode === "learn") {
    return (
      <LearnReviewModal
        deckId={deckId}
        isOpen={isOpen}
        onClose={onClose}
        minCardsRequired={MIN_ADVANCED_CARDS}
      />
    );
  }
  if (mode === "type") {
    return (
      <TypeReviewModal
        deckId={deckId}
        isOpen={isOpen}
        onClose={onClose}
        minCardsRequired={MIN_ADVANCED_CARDS}
      />
    );
  }
  if (mode === "spell") {
    return <SpellReviewModal deckId={deckId} isOpen={isOpen} onClose={onClose} />;
  }
  return (
    <MatchReviewModal
      deckId={deckId}
      isOpen={isOpen}
      onClose={onClose}
      minCardsRequired={MIN_ADVANCED_CARDS}
    />
  );
};
