import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import { GlassModal } from "@ui/components/GlassModal";
import { Button } from "@ui/components/Button";
import { useGrowl } from "@ui/components/Growl";
import { useTranslation } from "../i18n/I18nProvider";
import { useDeckReview } from "./useDeckReview";
import { ALL_MASTERY_FILTER, type CardMasteryFilter, type FlashOrderMode, type ReviewOrientation } from "./types";
import { ReviewStats } from "./ReviewStats";
import { ReviewSessionMenu } from "./ReviewSessionMenu";
import { SpellIcon } from "../components/icons";
import { formatAnswerDisplay } from "./formatAnswerDisplay";
import { useSessionLifecycle } from "./useSessionLifecycle";

type SpellReviewModalProps = {
  deckId?: string;
  isOpen: boolean;
  onClose: () => void;
  minCardsRequired?: number;
};

type LetterTile = {
  id: string;
  label: string;
};

type Segment =
  | {
      type: "slot";
      label: string;
      slotIndex: number;
    }
  | {
      type: "separator";
      label: string;
      key: string;
    };

const SUFFIX_CHARS = new Set(["'", "’"]);
const SEPARATOR_PATTERN = /[\s\-–—]/;

const shuffle = <T,>(input: T[]): T[] => {
  const copy = [...input];
  for (let i = copy.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = copy[i];
    copy[i] = copy[j] as T;
    copy[j] = tmp as T;
  }
  return copy;
};

const buildSegments = (value: string): Segment[] => {
  const normalized = value.normalize("NFC");
  const segments: Segment[] = [];
  let slotCount = 0;
  let lastSlot: Segment & { type: "slot" } | null = null;

  for (const char of normalized) {
    if (SEPARATOR_PATTERN.test(char)) {
      segments.push({
        type: "separator",
        label: char,
        key: `${segments.length}-${char}`
      });
      lastSlot = null;
      continue;
    }
    if (SUFFIX_CHARS.has(char) && lastSlot && lastSlot.type === "slot") {
      lastSlot.label = `${lastSlot.label}${char}`;
      continue;
    }
    const slotSegment: Segment & { type: "slot" } = {
      type: "slot",
      label: char,
      slotIndex: slotCount
    };
    segments.push(slotSegment);
    slotCount += 1;
    lastSlot = slotSegment;
  }

  return segments;
};

export const SpellReviewModal = ({
  deckId,
  isOpen,
  onClose,
  minCardsRequired = 1
}: SpellReviewModalProps) => {
  const { t } = useTranslation();
  const { showGrowl } = useGrowl();
  const [orientation, setOrientation] = useState<ReviewOrientation>("back-first");
  const [orderMode, setOrderMode] = useState<FlashOrderMode>("random");
  const [limitInput, setLimitInput] = useState("10");
  const [sessionVersion, setSessionVersion] = useState(0);
  const [placements, setPlacements] = useState<Array<string | null>>([]);
  const [activeSlotIndex, setActiveSlotIndex] = useState<number | null>(null);
  const [masteryFilter, setMasteryFilter] = useState<CardMasteryFilter>(ALL_MASTERY_FILTER);
  const [filterNotice, setFilterNotice] = useState<"none" | "insufficient" | null>(null);

  const limitValue = limitInput ? Math.max(1, parseInt(limitInput, 10) || 0) : undefined;
  const spellReview = useDeckReview(deckId, "spell", orientation, {
    orderMode,
    limit: limitValue,
    masteryFilter
  });
  const {
    deck,
    reviewState,
    currentCard,
    totalKnown,
    totalUnknown,
    startNewSession,
    startUnknownRound,
    markCardAsKnown,
    markCardAsUnknown,
    resetProgress
  } = spellReview;

  const filteredCards = spellReview.cards;
  const filteredCount = filteredCards.length;
  const hasCards = filteredCount > 0;
  const deckCardCount = deck?.cards.length ?? 0;
  const deckHasCards = deckCardCount > 0;
  const meetsDeckRequirement = deckCardCount >= minCardsRequired;
  const limitedCount = limitValue ? Math.min(filteredCount, limitValue) : filteredCount;
  const meetsFilteredRequirement = limitedCount >= minCardsRequired;
  const inProgress =
    reviewState != null &&
    reviewState.currentIndex < reviewState.cardOrder.length &&
    currentCard != null;
  const isSummary =
    reviewState != null && reviewState.currentIndex >= reviewState.cardOrder.length && hasCards;
  const nextRoundUnknownCount = reviewState?.unknownCardIds.length ?? 0;
  const canReviewUnknown = nextRoundUnknownCount > 0;

  const progressLabel = useMemo(() => {
    if (!reviewState || !currentCard) {
      return undefined;
    }
    return t("review.progress", {
      current: reviewState.currentIndex + 1,
      total: reviewState.cardOrder.length
    });
  }, [reviewState, currentCard, t]);

  const promptLabel = orientation === "front-first" ? t("review.cardFront") : t("review.cardBack");
  const buildLabel = orientation === "front-first" ? t("review.cardBack") : t("review.cardFront");
  const targetValue = currentCard?.back ?? "";

  const { segments, expectedLetters } = useMemo(() => {
    const builtSegments = buildSegments(targetValue);
    const slotSegs = builtSegments.filter(
      (segment): segment is Segment & { type: "slot" } => segment.type === "slot"
    );
    return {
      segments: builtSegments,
      expectedLetters: slotSegs.map((segment) => segment.label)
    };
  }, [targetValue]);
  const expectedLettersKey = useMemo(() => expectedLetters.join("|"), [expectedLetters]);
  const expectedLettersLength = expectedLetters.length;
  const expectedAnswer = useMemo(() => expectedLetters.join(""), [expectedLettersKey]);

  const letterTiles = useMemo<LetterTile[]>(() => {
    if (!currentCard) {
      return [];
    }
    const base = expectedLetters.map((label, index) => ({
      id: `${currentCard.id}-${index}`,
      label
    }));
    return shuffle(base);
  }, [currentCard?.id, expectedLettersKey]);

  const tileMap = useMemo(
    () =>
      letterTiles.reduce<Record<string, LetterTile>>((acc, tile) => {
        acc[tile.id] = tile;
        return acc;
      }, {}),
    [letterTiles]
  );

  const resetSession = useCallback(() => {
    setSessionVersion(0);
    setPlacements([]);
    setActiveSlotIndex(null);
    resetProgress();
    setFilterNotice(null);
  }, [resetProgress]);

  useEffect(() => {
    if (!isOpen) {
      resetSession();
    }
  }, [isOpen, resetSession]);

  useSessionLifecycle({
    isOpen,
    sessionVersion,
    canStart: hasCards,
    onReset: resetProgress,
    onStart: startNewSession
  });

  const masterySignatureRef = useRef(masteryFilter.join(","));
  useEffect(() => {
    const signature = masteryFilter.join(",");
    if (masterySignatureRef.current !== signature) {
      masterySignatureRef.current = signature;
      resetSession();
    }
  }, [masteryFilter, resetSession]);

  useEffect(() => {
    if (filterNotice && hasCards && meetsFilteredRequirement) {
      setFilterNotice(null);
    }
  }, [filterNotice, hasCards, meetsFilteredRequirement]);

  useEffect(() => {
    if (!currentCard) {
      setPlacements([]);
      setActiveSlotIndex(null);
      return;
    }
    setPlacements(Array(expectedLettersLength).fill(null));
    setActiveSlotIndex(expectedLettersLength > 0 ? 0 : null);
  }, [currentCard?.id, expectedLettersLength, expectedLettersKey, sessionVersion]);

  const startSession = useCallback(() => {
    if (!deckHasCards || !meetsDeckRequirement) return;
    if (!hasCards) {
      setFilterNotice("none");
      return;
    }
    if (!meetsFilteredRequirement) {
      setFilterNotice("insufficient");
      return;
    }
    setFilterNotice(null);
    setSessionVersion((prev) => prev + 1);
  }, [deckHasCards, meetsDeckRequirement, hasCards, meetsFilteredRequirement]);

  const handleOrderChange = useCallback(
    (value: FlashOrderMode) => {
      if (value === orderMode) return;
      setOrderMode(value);
      resetSession();
    },
    [orderMode, resetSession]
  );

  const handleOrientationChange = useCallback(
    (value: ReviewOrientation) => {
      if (value === orientation) return;
      setOrientation(value);
      resetSession();
    },
    [orientation, resetSession]
  );

  const handleLimitChange = useCallback(
    (value: string) => {
      const sanitized = value.replace(/[^\d]/g, "");
      setLimitInput(sanitized);
      resetSession();
    },
    [resetSession]
  );

  const handleLimitReset = useCallback(() => {
    setLimitInput("");
    resetSession();
  }, [resetSession]);

  const handleSlotClick = useCallback(
    (slotIndex: number) => {
      setActiveSlotIndex(slotIndex);
      setPlacements((prev) => {
        if (!prev[slotIndex]) {
          return prev;
        }
        const next = [...prev];
        next[slotIndex] = null;
        return next;
      });
    },
    []
  );

  const pickNextEmptySlot = useCallback(
    (current: number | null, nextState: Array<string | null>) => {
      if (nextState.length === 0) return null;
      const startIndex = current != null ? current + 1 : 0;
      for (let i = startIndex; i < nextState.length; i += 1) {
        if (!nextState[i]) return i;
      }
      for (let i = 0; i < nextState.length; i += 1) {
        if (!nextState[i]) return i;
      }
      return null;
    },
    []
  );

  const handleTilePick = useCallback(
    (tileId: string) => {
      setPlacements((prev) => {
        if (prev.includes(tileId)) {
          return prev;
        }
        const fallbackIndex = prev.findIndex((value) => value === null);
        const resolvedIndex =
          activeSlotIndex != null && !prev[activeSlotIndex] ? activeSlotIndex : fallbackIndex;
        if (resolvedIndex === -1) {
          return prev;
        }
        const next = [...prev];
        next[resolvedIndex] = tileId;
        const nextActive = pickNextEmptySlot(resolvedIndex, next);
        setActiveSlotIndex(nextActive ?? null);
        return next;
      });
    },
    [activeSlotIndex, pickNextEmptySlot]
  );

  const handleClearPlacements = useCallback(() => {
    setPlacements((prev) => (prev.length ? Array(prev.length).fill(null) : prev));
    setActiveSlotIndex(expectedLettersLength > 0 ? 0 : null);
  }, [expectedLettersLength]);

  const isComplete =
    expectedLettersLength > 0 &&
    placements.length === expectedLettersLength &&
    placements.every((value) => Boolean(value && tileMap[value]));

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (!currentCard || !isComplete) {
        return;
      }
      const attempt = placements
        .map((tileId) => (tileId ? tileMap[tileId]?.label ?? "" : ""))
        .join("");
      const expectedCanonical = expectedAnswer;
      const expectedDisplay = formatAnswerDisplay(targetValue.trim() || expectedAnswer);
      const isCorrect = attempt === expectedCanonical;
      if (isCorrect) {
        showGrowl({ tone: "success", message: t("review.spell.correct") });
        markCardAsKnown();
      } else {
        showGrowl({
          tone: "warning",
          message: t("review.spell.incorrect", { answer: expectedDisplay })
        });
        markCardAsUnknown();
      }
      setPlacements((prev) => (prev.length ? Array(prev.length).fill(null) : prev));
      setActiveSlotIndex(expectedLettersLength > 0 ? 0 : null);
    },
    [
      currentCard,
      expectedAnswer,
      expectedLettersLength,
      isComplete,
      markCardAsKnown,
      markCardAsUnknown,
      placements,
      showGrowl,
      t,
      tileMap,
      targetValue
    ]
  );

  const handleIDontKnow = useCallback(() => {
    if (!currentCard) {
      return;
    }
    const expectedDisplay = formatAnswerDisplay(targetValue.trim() || expectedAnswer);
    showGrowl({
      tone: "warning",
      message: t("review.spell.incorrect", { answer: expectedDisplay })
    });
    markCardAsUnknown();
    setPlacements((prev) => (prev.length ? Array(prev.length).fill(null) : prev));
    setActiveSlotIndex(expectedLettersLength > 0 ? 0 : null);
  }, [
    currentCard,
    expectedAnswer,
    expectedLettersLength,
    markCardAsUnknown,
    showGrowl,
    t,
    targetValue
  ]);

  const allCleared = placements.every((value) => value === null);

  return (
    <GlassModal open={isOpen} onClose={onClose} panelClassName="max-w-4xl" contentClassName="text-slate-900 dark:text-slate-50">
      <header className="flex flex-wrap items-start justify-between gap-3 md:gap-4">
        <div className="space-y-2">
          <p className="flex items-center gap-2 text-xs uppercase tracking-wide text-brand-400">
            <span className="text-brand-500">
              <SpellIcon className="h-4 w-4" />
            </span>
            {t("review.mode.spellLabel")}
          </p>
          <h2 className="text-xl md:text-2xl font-semibold text-slate-900 dark:text-slate-50">
            {deck ? deck.title : t("review.selectDeck")}
          </h2>
          {deck?.description && (
            <p className="hidden md:block text-sm text-slate-700 dark:text-slate-400">{deck.description}</p>
          )}
        </div>
      </header>

      {deck && !inProgress && (
        <ReviewSessionMenu
          order={{
            value: orderMode,
            onChange: handleOrderChange
          }}
          orientation={{
            value: orientation,
            onChange: handleOrientationChange
          }}
          limit={{
            value: limitInput,
            onChange: handleLimitChange,
            onReset: handleLimitReset
          }}
          mastery={{
            value: masteryFilter,
            onChange: (next) => {
              setMasteryFilter(next);
            }
          }}
          action={{
            label: sessionVersion > 0 ? t("review.flash.restartButton") : t("review.spell.startButton"),
            disabled: !deckHasCards || !meetsDeckRequirement,
            onClick: startSession
          }}
        />
      )}

      {!deckHasCards && (
        <div className="ui-empty-panel">
          {t("review.emptyDeck")}
        </div>
      )}
      {deckHasCards && !meetsDeckRequirement && (
        <div className="ui-empty-panel">
          {t("review.minCardsRequired", { count: minCardsRequired })}
        </div>
      )}
      {deckHasCards && meetsDeckRequirement && filterNotice === "none" && (
        <div className="ui-empty-panel">
          {t("review.filters.none")}
        </div>
      )}
      {deckHasCards && meetsDeckRequirement && filterNotice === "insufficient" && (
        <div className="ui-empty-panel">
          {t("review.filters.insufficient", { count: minCardsRequired })}
        </div>
      )}

      {hasCards && meetsDeckRequirement && inProgress && progressLabel && (
        <p className="mt-4 text-xs font-semibold uppercase tracking-wide text-[rgb(var(--theme-accent))]">
          {progressLabel}
        </p>
      )}

      {hasCards && meetsDeckRequirement && inProgress && currentCard && (
        <form className="ui-vstack-4" onSubmit={handleSubmit}>
          <div className="ui-card-panel text-sm space-y-4">
            <div className="space-y-1">
              <span className="ui-kicker">
                {promptLabel}
              </span>
              <p className="ui-prewrap ui-title-2xl">
                {currentCard.front}
              </p>
            </div>
            <div className="space-y-2">
              <span className="ui-kicker">
                {t("review.spell.targetLabel", { label: buildLabel })}
              </span>
              <p className="text-xs text-slate-500 dark:text-slate-400">
                {t("review.spell.instructions")}
              </p>
              <div className="flex flex-wrap gap-1.5 rounded-lg border border-slate-200/70 bg-white/70 p-3 dark:border-slate-700 dark:bg-slate-900/50 sm:gap-2">
                {segments.map((segment) =>
                  segment.type === "slot" ? (
                    <button
                      key={`slot-${segment.slotIndex}`}
                      type="button"
                      className={clsx(
                        "h-9 min-w-[2.1rem] rounded-lg border text-base font-semibold uppercase transition-colors sm:h-12 sm:min-w-[3rem] sm:text-lg",
                        placements[segment.slotIndex]
                          ? "border-brand-400 bg-brand-50 text-brand-700 dark:border-brand-500/60 dark:bg-brand-500/10 dark:text-brand-200"
                          : "border-slate-300 text-slate-400 dark:border-slate-700 dark:text-slate-600",
                        activeSlotIndex === segment.slotIndex && "ring-2 ring-brand-300"
                      )}
                      onClick={() => handleSlotClick(segment.slotIndex)}
                    >
                      {placements[segment.slotIndex]
                        ? tileMap[placements[segment.slotIndex] as string]?.label
                        : ""}
                    </button>
                  ) : (
                    <span
                      key={segment.key}
                      className="flex h-9 min-w-[0.85rem] items-center justify-center text-base font-semibold text-slate-400 dark:text-slate-600 sm:h-12 sm:min-w-[1rem] sm:text-lg"
                    >
                      {segment.label === " " ? "\u00A0" : segment.label}
                    </span>
                  )
                )}
              </div>
            </div>
            <div className="space-y-2">
              <span className="ui-kicker">
                {t("review.spell.availableLetters")}
              </span>
              <div className="flex flex-wrap gap-2">
                {letterTiles.map((tile) => {
                  const used = placements.includes(tile.id);
                  return (
                    <button
                      key={tile.id}
                      type="button"
                      onClick={() => handleTilePick(tile.id)}
                      disabled={used}
                      className={clsx(
                        "rounded-lg border px-3 py-2 text-base font-semibold uppercase transition",
                        used
                          ? "cursor-not-allowed border-slate-200/60 bg-slate-100/70 text-slate-400 dark:border-slate-700 dark:bg-slate-800/70 dark:text-slate-600 opacity-45"
                          : "border-slate-200 bg-white hover:border-brand-400 hover:text-brand-600 dark:border-slate-600 dark:bg-slate-800 dark:hover:border-brand-400 dark:hover:text-brand-200"
                      )}
                    >
                      {tile.label}
                    </button>
                  );
                })}
              </div>
            </div>
            <div className="flex flex-wrap gap-2">
              <Button type="submit" variant="primary" size="sm" disabled={!isComplete}>
                {t("review.spell.submit")}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="outline"
                onClick={handleClearPlacements}
                disabled={allCleared}
              >
                {t("review.spell.clear")}
              </Button>
              <Button
                type="button"
                size="sm"
                variant="warning"
                className="border-amber-300 bg-amber-50 text-slate-900 hover:bg-amber-100 focus-visible:outline-amber-300 dark:border-amber-300/60 dark:bg-amber-400/20 dark:text-white dark:hover:bg-amber-300/25"
                onClick={handleIDontKnow}
              >
                {t("review.idkButton")}
              </Button>
            </div>
          </div>
        </form>
      )}

      {hasCards && meetsDeckRequirement && isSummary && reviewState && (
        <ReviewStats
          totalCards={totalKnown + totalUnknown}
          knownCards={totalKnown}
          unknownCards={totalUnknown}
          round={reviewState.round}
          nextRoundUnknown={nextRoundUnknownCount}
          onRestartUnknown={() => {
            if (canReviewUnknown) {
              startUnknownRound();
            }
          }}
        />
      )}
    </GlassModal>
  );
};
