import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useDeckStore } from "../decks/useDeckStore";
import type { ReviewOrientation, MatchGrid } from "./types";
import type { MatchResult } from "@core/models";

type MatchTile = {
  key: string;
  cardId: string;
  side: "front" | "back";
  text: string;
  matched: boolean;
};

type SimpleCardSource = {
  id: string;
  front: string;
  back: string;
};

const EMPTY_CARD_LIST: SimpleCardSource[] = [];

const nanoKey = () => Math.random().toString(36).slice(2) + Date.now().toString(36);

/**
 * Build tiles for the match game.
 * We create pairs from card.front and card.back.
 * If the grid capacity exceeds the number of available pairs, we limit to available cards.
 */
const buildTiles = (
  cards: { id: string; front: string; back: string }[],
  grid: MatchGrid
): { tiles: MatchTile[]; pairs: number } => {
  const capacity = grid.rows * grid.cols;
  const wantedPairs = Math.floor(capacity / 2);
  const pairs = Math.min(wantedPairs, cards.length);

  const shuffled = [...cards];
  for (let i = shuffled.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = shuffled[i]!;
    shuffled[i] = shuffled[j]!;
    shuffled[j] = tmp;
  }
  const selected = shuffled.slice(0, pairs);
  const tiles: MatchTile[] = [];
  for (const c of selected) {
    tiles.push(
      {
        key: `${c.id}-front-${nanoKey()}`,
        cardId: c.id,
        side: "front",
        text: c.front,
        matched: false
      },
      {
        key: `${c.id}-back-${nanoKey()}`,
        cardId: c.id,
        side: "back",
        text: c.back,
        matched: false
      }
    );
  }
  for (let i = tiles.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = tiles[i]!;
    tiles[i] = tiles[j]!;
    tiles[j] = tmp;
  }
  return { tiles, pairs };
};

export type UseMatchReviewState = {
  deck:
    | {
        id: string;
        title: string;
        description?: string;
        cards: { id: string; front: string; back: string }[];
        matchResults: MatchResult[];
      }
    | undefined;
  grid: MatchGrid;
  setGrid: (grid: MatchGrid) => void;
  tiles: MatchTile[];
  selected: number[]; // indices into tiles
  selectTile: (index: number) => void;
  mistakes: number;
  elapsedMs: number;
  completed: boolean;
  score: number;
  pairs: number;
  started: boolean;
  canStart: boolean;
  startGame: () => void;
  stopGame: () => void;
  latestResultTimestamp: number | null;
};

export const useMatchReview = (
  deckId: string | undefined,
  _orientation: ReviewOrientation // kept for future extension; currently unused since game uses both sides
): UseMatchReviewState => {
  const deck = useDeckStore((s) => s.decks.find((d) => d.id === deckId));
  const addMatchResult = useDeckStore((s) => s.addMatchResult);

  // Default to 5 matching pairs (two columns layout)
  const [grid, setGrid] = useState<MatchGrid>({ rows: 5, cols: 2 });

  const cardSignature = useMemo(() => {
    if (!deck || !deck.cards) return "";
    return deck.cards
      .map((c) => {
        const timestamp =
          c.updatedAt instanceof Date ? c.updatedAt.getTime() : Number(new Date(c.updatedAt));
        return `${c.id}:${c.front}:${c.back}:${timestamp}`;
      })
      .join("|");
  }, [deck]);

  const simpleCards = useMemo<SimpleCardSource[]>(() => {
    if (!deck || !deck.cards) {
      return EMPTY_CARD_LIST;
    }
    return deck.cards.map((c) => ({ id: c.id, front: c.front, back: c.back }));
  }, [cardSignature, deck?.id]);

  const initialBuildRef = useRef<{ tiles: MatchTile[]; pairs: number } | null>(null);
  const completionLoggedRef = useRef(false);

  const ensureInitialBuild = useCallback(() => {
    initialBuildRef.current = buildTiles(simpleCards, grid);
  }, [simpleCards, grid]);

  // Build tiles when deck/grid changes
  useEffect(() => {
    ensureInitialBuild();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [deckId, cardSignature, grid.rows, grid.cols]);

  const [tiles, setTiles] = useState<MatchTile[]>([]);
  const [pairs, setPairs] = useState(0);
  const [selected, setSelected] = useState<number[]>([]);
  const [mistakes, setMistakes] = useState(0);
  const [completed, setCompleted] = useState(false);
  const [score, setScore] = useState(0);
  const [startAt, setStartAt] = useState<number | null>(null);
  const [endAt, setEndAt] = useState<number | null>(null);
  const [now, setNow] = useState(Date.now());
  const [started, setStarted] = useState(false);
  const [latestResultTimestamp, setLatestResultTimestamp] = useState<number | null>(null);
  const [pendingResult, setPendingResult] = useState<MatchResult | null>(null);

  const clearBoard = useCallback(() => {
    setTiles([]);
    setPairs(0);
    setSelected([]);
    setMistakes(0);
    setCompleted(false);
    setScore(0);
    setStartAt(null);
    setEndAt(null);
    setNow(Date.now());
    completionLoggedRef.current = false;
    setLatestResultTimestamp(null);
    setPendingResult(null);
  }, []);

  // Initialize tiles from initialBuildRef
  const resetFromBuild = useCallback(() => {
    const build = initialBuildRef.current ?? buildTiles(simpleCards, grid);
    setTiles(build.tiles);
    setPairs(build.pairs);
    setSelected([]);
    setMistakes(0);
    setCompleted(false);
    setScore(0);
    setStartAt(null);
    setEndAt(null);
    setNow(Date.now());
  }, [grid, simpleCards]);

  const canStart = simpleCards.length >= 2;

  const startGame = useCallback(() => {
    if (!canStart) return;
    ensureInitialBuild();
    resetFromBuild();
    setStarted(true);
    completionLoggedRef.current = false;
    setLatestResultTimestamp(null);
    setPendingResult(null);
  }, [canStart, ensureInitialBuild, resetFromBuild]);

  const stopGame = useCallback(() => {
    clearBoard();
    ensureInitialBuild();
    setStarted(false);
  }, [clearBoard, ensureInitialBuild]);

  useEffect(() => {
    ensureInitialBuild();
    clearBoard();
    setStarted(false);
  }, [ensureInitialBuild, clearBoard, deckId, cardSignature, grid.rows, grid.cols]);

  useEffect(() => {
    if (!deckId || !pendingResult) {
      return;
    }
    addMatchResult(deckId, pendingResult);
    setPendingResult(null);
  }, [deckId, pendingResult, addMatchResult]);

  // timer updating
  useEffect(() => {
    if (!startAt || completed) return;
    const id = window.setInterval(() => setNow(Date.now()), 100);
    return () => window.clearInterval(id);
  }, [startAt, completed]);

  const elapsedMs = useMemo(() => {
    if (!startAt) return 0;
    return (endAt ?? now) - startAt;
  }, [startAt, endAt, now]);

  const finalizeMatch = useCallback(
    (mistakeCount: number) => {
      if (completionLoggedRef.current) return;
      completionLoggedRef.current = true;

      const finishedAt = Date.now();
      setCompleted(true);
      setEndAt(finishedAt);
      const timeSec = ((finishedAt - (startAt ?? finishedAt)) / 1000) || 0;
      const raw = Math.round((pairs * 1000) / (timeSec + 5) + pairs * 50 - mistakeCount * 25);
      const finalScore = Math.max(0, Math.min(100000, raw));
      setScore(finalScore);

      const result: MatchResult = {
        rows: grid.rows,
        cols: grid.cols,
        pairs,
        timeMs: Math.max(0, finishedAt - (startAt ?? finishedAt)),
        mistakes: mistakeCount,
        score: finalScore,
        completedAt: new Date()
      };
      setPendingResult(result);
      setLatestResultTimestamp(result.completedAt.getTime());
    },
    [pairs, grid.rows, grid.cols, startAt]
  );

  useEffect(() => {
    if (!started || completed) return;
    if (tiles.length === 0) return;
    if (tiles.every((tile) => tile.matched)) {
      finalizeMatch(mistakes);
    }
  }, [tiles, started, completed, mistakes, finalizeMatch]);

  const applyMatch = useCallback(
    (a: number, b: number) => {
      let shouldFinalize = false;
      setTiles((prev) => {
        const next = prev.slice();
        const ta = next[a];
        const tb = next[b];
        if (!ta || !tb) {
          return prev;
        }
        next[a] = { ...ta, matched: true } as MatchTile;
        next[b] = { ...tb, matched: true } as MatchTile;
        shouldFinalize = next.every((tile) => tile.matched);
        return next;
      });
      setSelected([]);
      if (shouldFinalize) {
        finalizeMatch(mistakes);
      }
    },
    [finalizeMatch, mistakes]
  );

  const applyMismatch = useCallback(
    (a: number, b: number) => {
      setMistakes((m) => m + 1);
      // Briefly show both selected then clear
      window.setTimeout(() => {
        setSelected([]);
      }, 600);
    },
    []
  );

  const selectTile = useCallback(
    (index: number) => {
      if (!started || completed) return;
      if (!tiles[index] || tiles[index].matched) return;

      setSelected((sel) => {
        if (sel.includes(index)) {
          return sel;
        }
        const nextSel = sel.length === 0 ? [index] : [sel[0]!, index];

        if (!startAt) {
          setStartAt(Date.now());
        }

        if (nextSel.length === 2) {
          const [a, b] = nextSel as [number, number];
          const A = tiles[a];
          const B = tiles[b];
          if (A && B) {
            if (A.cardId === B.cardId && A.side !== B.side) {
              // match
              applyMatch(a, b);
            } else {
              // mismatch
              applyMismatch(a, b);
            }
          }
        }

        return nextSel;
      });
    },
    [tiles, completed, startAt, applyMatch, applyMismatch, started]
  );

  const publicDeck = useMemo(() => {
    if (!deck) return undefined;
    return {
      id: deck.id,
      title: deck.title,
      ...(deck.description ? { description: deck.description } : {}),
      cards: deck.cards.map((c) => ({ id: c.id, front: c.front, back: c.back })),
      matchResults: deck.matchResults ?? []
    };
  }, [deck]);

  return {
    deck: publicDeck,
    grid,
    setGrid,
    tiles,
    selected,
    selectTile,
    mistakes,
    elapsedMs,
    completed,
    score,
    pairs,
    started,
    canStart,
    startGame,
    stopGame,
    latestResultTimestamp
  };
};
