import { useEffect, useMemo, useRef, useState } from "react";
import clsx from "clsx";
import { GlassModal } from "@ui/components/GlassModal";
import { useTranslation } from "../i18n/I18nProvider";

const DAYS_PER_WEEK = 7;
const DEFAULT_WEEK_COUNT = 52;
const formatDateKey = (date: Date) => date.toISOString().slice(0, 10);
const WEEKDAY_LABELS = ["S", "M", "T", "W", "T", "F", "S"];
const GRID_MIN_WIDTH = 640;

const levelClasses = [
  // 0 = no activity: keep subtle but visible on dark panels
  "border border-slate-700/70 bg-slate-900/80 dark:border-white/10 dark:bg-white/5",
  // 1-4 = progressively stronger contrast
  "border border-sky-400/80 bg-sky-300/80 dark:border-sky-400/80 dark:bg-sky-400/45",
  "border border-sky-500 bg-sky-400/90 dark:border-sky-300/90 dark:bg-sky-500/70",
  "border border-sky-600 bg-sky-500 dark:border-sky-200/90 dark:bg-sky-600/80",
  "border border-blue-700 bg-blue-600 dark:border-blue-200/90 dark:bg-blue-500"
];

type StreakHistoryModalProps = {
  open: boolean;
  onClose: () => void;
  streakCount: number;
  reviewActivity: Record<string, number>;
};

type HeatmapCell = {
  key: string;
  date: Date;
  value: number;
};

const buildHeatmapCells = (
  activity: Record<string, number>,
  totalDays: number,
  startDate: Date
): HeatmapCell[] => {
  return Array.from({ length: totalDays }).map((_, index) => {
    const date = new Date(startDate);
    date.setDate(startDate.getDate() + index);
    const key = formatDateKey(date);
    return {
      key,
      date,
      value: activity[key] ?? 0
    };
  });
};

const computeAlignedRange = (weeks: number, endDate: Date) => {
  const normalizedEnd = new Date(endDate);
  normalizedEnd.setHours(0, 0, 0, 0);
  const alignedEnd = new Date(normalizedEnd);
  const dayOfWeek = alignedEnd.getDay();
  alignedEnd.setDate(alignedEnd.getDate() + (DAYS_PER_WEEK - 1 - dayOfWeek));
  const totalDays = weeks * DAYS_PER_WEEK;
  const startDate = new Date(alignedEnd);
  startDate.setDate(alignedEnd.getDate() - (totalDays - 1));
  return {
    startDate,
    endDate: alignedEnd
  };
};

const getIntensityLevel = (value: number, maxValue: number) => {
  if (value <= 0 || maxValue <= 0) {
    return 0;
  }
  if (maxValue <= levelClasses.length - 1) {
    return Math.min(levelClasses.length - 1, value);
  }
  const ratio = value / maxValue;
  if (ratio >= 0.8) return 4;
  if (ratio >= 0.6) return 3;
  if (ratio >= 0.35) return 2;
  return 1;
};

export const StreakHistoryModal = ({
  open,
  onClose,
  streakCount,
  reviewActivity
}: StreakHistoryModalProps) => {
  const { t } = useTranslation();
  const [weekOffset, setWeekOffset] = useState(0);
  const gridWrapperRef = useRef<HTMLDivElement | null>(null);
  const [gridWidth, setGridWidth] = useState(0);
  useEffect(() => {
    const element = gridWrapperRef.current;
    if (!element) {
      return undefined;
    }
    const observer = new ResizeObserver((entries) => {
      if (entries[0]) {
        setGridWidth(entries[0].contentRect.width);
      }
    });
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  const earliestActivityDate = useMemo(() => {
    const keys = Object.keys(reviewActivity).sort();
    if (keys.length === 0) {
      return undefined;
    }
    return new Date(keys[0]);
  }, [reviewActivity]);
  const referenceEndDate = useMemo(() => {
    const now = new Date();
    now.setHours(0, 0, 0, 0);
    now.setDate(now.getDate() - weekOffset * DAYS_PER_WEEK);
    return now;
  }, [weekOffset]);
  const totalDays = DEFAULT_WEEK_COUNT * DAYS_PER_WEEK;
  const range = useMemo(
    () => computeAlignedRange(DEFAULT_WEEK_COUNT, referenceEndDate),
    [referenceEndDate]
  );
  const cells = useMemo(
    () => buildHeatmapCells(reviewActivity, totalDays, range.startDate),
    [reviewActivity, totalDays, range.startDate]
  );
  const maxValue = useMemo(
    () => cells.reduce((max, cell) => Math.max(max, cell.value), 0),
    [cells]
  );
  const activeDays = useMemo(() => cells.filter((cell) => cell.value > 0).length, [cells]);
  const weeks = useMemo(() => {
    const result: HeatmapCell[][] = [];
    for (let weekIndex = 0; weekIndex < cells.length / DAYS_PER_WEEK; weekIndex += 1) {
      const start = weekIndex * DAYS_PER_WEEK;
      result.push(cells.slice(start, start + DAYS_PER_WEEK));
    }
    return result;
  }, [cells]);
  const canShowOlder = earliestActivityDate
    ? range.startDate.getTime() > earliestActivityDate.getTime()
    : false;
  const canShowNewer = weekOffset > 0;
  const tooltipFormatter = useMemo(
    () =>
      new Intl.DateTimeFormat(undefined, {
        weekday: "short",
        month: "short",
        day: "numeric"
      }),
    []
  );
  const monthInitialFormatter = useMemo(
    () =>
      new Intl.DateTimeFormat(undefined, {
        month: "narrow"
      }),
    []
  );
  const rangeFormatter = useMemo(
    () =>
      new Intl.DateTimeFormat(undefined, {
        month: "short",
        day: "numeric",
        year: "numeric"
      }),
    []
  );

  const monthLabels = useMemo(() => {
    let previousMonth: number | undefined;
    return weeks.map((week, index) => {
      const cell = week[0];
      if (!cell) return { key: `empty-${index}`, label: "" };
      const month = cell.date.getMonth();
      const label = previousMonth === month ? "" : monthInitialFormatter.format(cell.date);
      previousMonth = month;
      return { key: `${cell.key}-${index}`, label };
    });
  }, [weeks, monthInitialFormatter]);

  const weekdayLabels = WEEKDAY_LABELS;

  const handleShowOlder = () => {
    if (!canShowOlder) return;
    setWeekOffset((prev) => prev + DEFAULT_WEEK_COUNT);
  };

  const handleShowNewer = () => {
    if (!canShowNewer) return;
    setWeekOffset((prev) => Math.max(0, prev - DEFAULT_WEEK_COUNT));
  };

  const cellSizePx = useMemo(() => {
    if (weeks.length === 0) {
      return 12;
    }
    const effectiveWidth = Math.max(gridWidth, GRID_MIN_WIDTH);
    const computed = effectiveWidth / weeks.length;
    return Math.max(8, Math.min(16, computed));
  }, [gridWidth, weeks.length]);
  const cellSizeExpression = `${cellSizePx}px`;
  const rangeLabel = `${rangeFormatter.format(range.startDate)} – ${rangeFormatter.format(range.endDate)}`;

  return (
    <GlassModal
      open={open}
      onClose={onClose}
      overlayClassName="items-start p-0"
      panelClassName="h-full md:h-[100dvh] md:max-w-5xl md:rounded-[16px]"
      contentClassName="gap-4 w-full max-w-5xl mx-auto px-5 py-6 sm:px-10 sm:py-8"
      closeAriaLabel={t("deck.streakHistoryClose")}
    >
      <header className="space-y-2 px-5 sm:px-10">
        <h3 className="text-2xl font-semibold text-slate-100">
          {t("deck.streakHistoryTitle")}
        </h3>
        <p className="text-sm text-slate-400">
          {t("deck.streakHistoryDescription")}
        </p>
      </header>

      <div className="inline-flex items-center gap-2 self-start rounded-full border border-slate-700/70 bg-slate-900/60 px-3 py-1 text-sm text-slate-200 shadow-sm mx-5 sm:mx-10">
        <button
          type="button"
          onClick={handleShowOlder}
          disabled={!canShowOlder}
          className="rounded-full px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-slate-400 transition hover:text-white disabled:opacity-30"
        >
          ◀
        </button>
        <span className="text-xs font-medium uppercase tracking-wide text-slate-200">
          {rangeLabel}
        </span>
        <button
          type="button"
          onClick={handleShowNewer}
          disabled={!canShowNewer}
          className="rounded-full px-2 py-0.5 text-xs font-semibold uppercase tracking-wide text-slate-400 transition hover:text-white disabled:opacity-30"
        >
          ▶
        </button>
      </div>

      <div className="w-full overflow-x-auto px-5 sm:px-10">
        <div
          ref={gridWrapperRef}
          className="grid rounded-[16px] text-[10px] uppercase tracking-widest text-slate-400"
          style={{
            minWidth: GRID_MIN_WIDTH,
            gridTemplateColumns: `repeat(${weeks.length + 1}, minmax(0, 1fr))`,
            gridTemplateRows: `repeat(${DAYS_PER_WEEK + 1}, ${cellSizeExpression})`,
            columnGap: 1,
            rowGap: 1
          }}
        >
          <span />
          {monthLabels.map((month, index) => (
            <span
              key={month.key}
              className="flex items-center justify-center text-[8px] font-semibold"
              style={{
                gridColumnStart: index + 2,
                gridRowStart: 1
              }}
            >
              {month.label}
            </span>
          ))}
          {weekdayLabels.map((label, index) => (
            <span
              key={`${label}-${index}`}
              className="flex items-center justify-center"
              style={{
                gridColumnStart: 1,
                gridRowStart: index + 2
              }}
            >
              {label}
            </span>
          ))}
          {cells.map((cell, index) => {
            const level = getIntensityLevel(cell.value, maxValue);
            const label = tooltipFormatter.format(cell.date);
            const tooltip =
              cell.value > 0
                ? t("deck.streakHistoryTooltipActive", {
                    count: cell.value,
                    date: label
                  })
                : t("deck.streakHistoryTooltipEmpty", { date: label });
            const column = Math.floor(index / DAYS_PER_WEEK) + 2;
            const row = (index % DAYS_PER_WEEK) + 2;
            return (
              <div
                key={cell.key}
                className={clsx("transition-colors duration-200", levelClasses[level])}
                style={{
                  gridColumnStart: column,
                  gridRowStart: row,
                  width: cellSizeExpression,
                  height: cellSizeExpression
                }}
                title={tooltip}
                aria-label={tooltip}
              />
            );
          })}
        </div>
      </div>
    </GlassModal>
  );
};
