import axios from "axios";

const DRIVE_API_BASE_URL = "https://www.googleapis.com/drive/v3";
const DRIVE_UPLOAD_BASE_URL = "https://www.googleapis.com/upload/drive/v3";

export type DriveFileSummary = {
  id: string;
  name: string;
  modifiedTime: string;
};

const ensureAccessToken = (accessToken: string) => {
  if (!accessToken) {
    throw new Error("Access token is required to query Google Drive.");
  }
};

const buildMultipartBody = (metadata: Record<string, unknown>, content: unknown) => {
  const boundary = `mova-${Math.random().toString(36).slice(2)}`;
  const body = [
    `--${boundary}`,
    "Content-Type: application/json; charset=UTF-8",
    "",
    JSON.stringify(metadata),
    `--${boundary}`,
    "Content-Type: application/json; charset=UTF-8",
    "",
    typeof content === "string" ? content : JSON.stringify(content),
    `--${boundary}--`,
    ""
  ].join("\r\n");

  return { body, boundary };
};

export const listAppDataFiles = async (
  accessToken: string,
  options: { pageSize?: number; query?: string } = {}
) => {
  ensureAccessToken(accessToken);

  const response = await axios.get<{ files?: DriveFileSummary[] }>(`${DRIVE_API_BASE_URL}/files`, {
    params: {
      spaces: "appDataFolder",
      fields: "files(id,name,modifiedTime)",
      pageSize: options.pageSize ?? 100,
      q: options.query
    },
    headers: {
      Authorization: `Bearer ${accessToken}`
    }
  });

  return response.data.files ?? [];
};

export const downloadAppDataFile = async (accessToken: string, fileId: string) => {
  ensureAccessToken(accessToken);
  const response = await axios.get(`${DRIVE_API_BASE_URL}/files/${fileId}`, {
    params: {
      alt: "media"
    },
    headers: {
      Authorization: `Bearer ${accessToken}`
    }
  });
  return response.data;
};

export const createAppDataJsonFile = async (
  accessToken: string,
  name: string,
  content: unknown
) => {
  ensureAccessToken(accessToken);
  const metadata = {
    name,
    parents: ["appDataFolder"],
    mimeType: "application/json"
  };
  const { body, boundary } = buildMultipartBody(metadata, content);
  const response = await axios.post<DriveFileSummary>(
    `${DRIVE_UPLOAD_BASE_URL}/files?uploadType=multipart`,
    body,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": `multipart/related; boundary=${boundary}`
      }
    }
  );
  return response.data;
};

export const updateAppDataJsonFile = async (
  accessToken: string,
  fileId: string,
  content: unknown
) => {
  ensureAccessToken(accessToken);
  const metadata = {
    mimeType: "application/json"
  };
  const { body, boundary } = buildMultipartBody(metadata, content);
  const response = await axios.patch<DriveFileSummary>(
    `${DRIVE_UPLOAD_BASE_URL}/files/${fileId}?uploadType=multipart`,
    body,
    {
      headers: {
        Authorization: `Bearer ${accessToken}`,
        "Content-Type": `multipart/related; boundary=${boundary}`
      }
    }
  );
  return response.data;
};

export const deleteAppDataFile = async (accessToken: string, fileId: string) => {
  ensureAccessToken(accessToken);
  await axios.delete(`${DRIVE_API_BASE_URL}/files/${fileId}`, {
    headers: {
      Authorization: `Bearer ${accessToken}`
    }
  });
};
