import { useCallback, useState } from "react";
import { nanoid } from "nanoid";
import type { DraftCard } from "./deckFormTypes";

type TranslateFn = (key: string, values?: Record<string, string | number>) => string;

type UseCsvImporterOptions = {
  t: TranslateFn;
  setDraftCards: React.Dispatch<React.SetStateAction<DraftCard[]>>;
};

export const useCsvImporter = ({ t, setDraftCards }: UseCsvImporterOptions) => {
  const [fileError, setFileError] = useState<string>();

  const handleCsvImport = useCallback(
    (event: React.ChangeEvent<HTMLInputElement>) => {
      const file = event.target.files?.[0];
      if (!file) return;
      if (!file.type.includes("csv") && !file.name.endsWith(".csv")) {
        setFileError(t("deck.csv.invalidType"));
        return;
      }
      const reader = new FileReader();
      reader.onload = () => {
        const text = reader.result?.toString() ?? "";
        const rows = text
          .split(/\r?\n/)
          .slice(1)
          .map((line) => line.trim())
          .filter(Boolean);
        if (rows.length === 0) {
          setFileError(t("deck.csv.empty"));
          return;
        }
        const parsedCards = rows
          .map((row) => {
            const [front, back] = row.split(",");
            if (!front || !back) return null;
            return {
              tempId: nanoid(),
              front: front.replace(/^"|"$/g, "").replace(/""/g, '"'),
              back: back.replace(/^"|"$/g, "").replace(/""/g, '"')
            };
          })
          .filter((card): card is DraftCard => Boolean(card));
        if (parsedCards.length === 0) {
          setFileError(t("deck.csv.empty"));
          return;
        }
        setDraftCards((prev) => [...prev, ...parsedCards]);
        setFileError(undefined);
        event.target.value = "";
      };
      reader.onerror = () => {
        setFileError(t("deck.csv.readError"));
        event.target.value = "";
      };
      reader.readAsText(file);
    },
    [t, setDraftCards]
  );

  return { fileError, handleCsvImport };
};
